entries[136339] = { ["name"] = "Zauberstein von Kel'danath", ["text"] = "Questgegenstand\nBenutzen: Kostet 20 uraltes Mana.\n\nBetört den anvisierten Verdorrten, sodass er innerhalb Suramars für Euch kämpft.\n\nEs können gleichzeitig bis zu 5 Verdorrte unter Eurer Betörung stehen." }
entries[136342] = { ["name"] = "Obliterumasche", ["text"] = "Handwerksmaterial\n\"Dieses Material scheint all seine Macht verloren zu haben.\"\nVerkaufspreis:" }
entries[136343] = { ["name"] = "Begehrte Hufe", ["text"] = "Questgegenstand\n\"Diese gesplitterten und abgenutzten Hufe erzählen eine eigene Geschichte.\"" }
entries[136350] = { ["name"] = "Brumdysla, Hammer von Vrorsk", ["text"] = "Werkzeug für Schmiedekunst Haltbarkeit 16 / 16\n\"Dieser uralte Vrykulhammer kann anstelle eines normalen Schmiedehammers für Handwerksprojekte verwendet werden.\"\nVerkaufspreis:" }
entries[136351] = { ["name"] = "Handvoll Obliterumasche", ["text"] = "Questgegenstand" }
entries[136352] = { ["name"] = "Erzmagier Karlains machtgetränkte seidengewebte Robe", ["text"] = "Questgegenstand\nVerkaufspreis:" }
entries[136353] = { ["name"] = "Zerbrochenes Totem", ["text"] = "\"Nutzlos... Vielleicht könnt Ihr jemanden finden, der es Euch zur Weiterverwertung abkauft.\"\nVerkaufspreis:" }
entries[136354] = { ["name"] = "Zerfallene Reagenzien", ["text"] = "\"Was auch immer das einst war, es ist nicht mehr zu erkennen und keinesfalls magisch.\"\nVerkaufspreis:" }
entries[136355] = { ["name"] = "Zerkratzter Runenstock", ["text"] = "\"Man kann kaum noch erkennen, was darauf geschrieben steht. Vielleicht braucht irgendjemand etwas Feuerholz.\"\nVerkaufspreis:" }
entries[136356] = { ["name"] = "Kompendium uralter Waffen, Band I", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lesen, um neues Wissen über Euer Artefakt zu erlangen und die Rate zu erhöhen, mit der Ihr Artefaktmacht erlangt.\n\"Eine ausführliche Aufzählung vieler der großen Waffen, die eine Rolle in der Geschichte Azeroths spielten.\"" }
entries[136357] = { ["name"] = "Schimmerndes Elixier der Verlangsamung", ["text"] = "Questgegenstand\n\"Ihr hofft, dass dieses Tonikum, welches aus in Val'sharah heimischen Zutaten zusammengemischt wurde, besser schmeckt, als es riecht.\"" }
entries[136358] = { ["name"] = "Opfergaben für Ursol", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Opfergaben sind aus einem mit Malachitsplittern verzierten Bärenzahn gefertigt.\"" }
entries[136359] = { ["name"] = "Schamanenbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Mal schauen, was der Schamane bei sich hatte...\"\n<Zum Öffnen rechtsklicken>" }
entries[136360] = { ["name"] = "Kristallines Dämonenauge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nVerkaufspreis:" }
entries[136361] = { ["name"] = "Zerschmetterte Rüstung", ["text"] = "Wird beim Aufheben gebunden\n\"Teile einer Rüstung aus einer längst vergangenen Schlacht.\"\nVerkaufspreis:" }
entries[136362] = { ["name"] = "Uralte Kriegsüberreste", ["text"] = "Wird beim Aufheben gebunden\n\"Während des Krieges der Ahnen war Sturmheim Schauplatz unzähliger brutaler Schlachten.\"\n<Zum Öffnen rechtsklicken>" }
entries[136363] = { ["name"] = "Galius' Geständnis", ["text"] = "Questgegenstand\n\"Das in Eile geschriebene Schriftstück ist kaum lesbar.\"" }
entries[136369] = { ["name"] = "Sturmschwingenschuppe", ["text"] = "Questgegenstand\n\"Selbst im Tod knistert diese Schuppe noch vor Elektrizität.\"" }
entries[136370] = { ["name"] = "Zerborstener Sturmschwingenschädel", ["text"] = "Questgegenstand\n\"Dieser Schädel ähnelt kaum noch seiner Originalform.\"" }
entries[136371] = { ["name"] = "Riesiger Sturmschwingenschädel", ["text"] = "Questgegenstand\n\"Dies ist der beste Drachenschädel, den Ihr je gesehen habt.\"" }
entries[136372] = { ["name"] = "Archäologenpfeife", ["text"] = "Questgegenstand" }
entries[136373] = { ["name"] = "Wurmglasschwimmer", ["text"] = "Benutzen: Ersetzt 30 Min. lang Euren Schwimmer mit einer Dose (zumindest für Fische) schmackhafter Würmer.\nVerkaufspreis:" }
entries[136374] = { ["name"] = "Spielzeugkatzenkopfschwimmer", ["text"] = "Benutzen: Ersetzt 30 Min. lang Euren Schwimmer mit einem Spielzeugkatzenkopf.\nVerkaufspreis:" }
entries[136375] = { ["name"] = "Quietscheentenschwimmer", ["text"] = "Benutzen: Ersetzt 30 Min. lang Euren Schwimmer mit einer Quietscheente.\nBenötigt Beschwörer Margoss\n- Freund" }
entries[136376] = { ["name"] = "Murlocschwimmer", ["text"] = "Benutzen: Ersetzt 30 Min. lang Euren Schwimmer mit einem niedlichen Murlockopf.\nBenötigt Beschwörer Margoss\n- Freund" }
entries[136377] = { ["name"] = "Übergroßer Schwimmer", ["text"] = "Benutzen: Erhöht 1 Stunde lang die Größe Eures gewöhnlichen Schwimmers.\nVerkaufspreis:" }
entries[136381] = { ["name"] = "Kunstvoll verzierter Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Ränder des Schlüssels sind abgenutzt, aber das Kopfstück ist mit wertvollen Metallen und Edelsteinen verziert.\"\nVerkaufspreis:" }
entries[136382] = { ["name"] = "Besitzurkunden des Hauses Rabenkrone", ["text"] = "Wird beim Aufheben gebunden\n\"Verschiedene Eigentumsdokumente über die Ländereien des Hauses Rabenkrone.\"\nVerkaufspreis:" }
entries[136383] = { ["name"] = "Schatulle des Hauses Rabenkrone", ["text"] = "Wird beim Aufheben gebunden\n\"Mit einem Rabeninsigne versehen.\"\n<Zum Öffnen rechtsklicken>" }
entries[136385] = { ["name"] = "Kristallisierte Seele", ["text"] = "Questgegenstand\n\"Ihr hört einen schwachen Schrei tief im Inneren.\"" }
entries[136386] = { ["name"] = "Blutstein", ["text"] = "Questgegenstand\nBenutzen: Kanalisiert die Macht des Blutsteins. (4 Sek. Abklingzeit)\n\"Von brillanter Farbe und warm.\"" }
entries[136389] = { ["name"] = "Der Höllenkodex", ["text"] = "Questgegenstand\n\"Ein uralter Text, der die Kreation von Höllenbestien beschreibt.\"" }
entries[136391] = { ["name"] = "Verderbte Blütenblätter", ["text"] = "Questgegenstand\n\"Dunkle Energie glüht tiefrot im Innern.\"" }
entries[136394] = { ["name"] = "Trupp Ochseninitianden", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136397] = { ["name"] = "Staubiges Scheibenfragment", ["text"] = "Questgegenstand\n\"Ein kleines Teil einer viel größeren Titanenscheibe.\"" }
entries[136398] = { ["name"] = "Uralte Phiole", ["text"] = "Questgegenstand\n\"Die Phiole selbst ist gesprungen und staubig, doch die Flüssigkeit darin schillert noch immer blendend hell.\"" }
entries[136400] = { ["name"] = "Schatteneissplitter", ["text"] = "Questgegenstand\nEinzigartig (30)\n\"Ein schattenhafter Eissplitter, der von einem Anhänger der Finsternis mitgeführt wurde.\"" }
entries[136403] = { ["name"] = "Stab der Vier Winde", ["text"] = "Questgegenstand\nBenutzen: Beschwört Donneraan den Windlord zum Vortexgipfel." }
entries[136404] = { ["name"] = "Trupp Tigerinitianden", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136405] = { ["name"] = "Schüler von Chi-Ji - Kranichinitiand", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136406] = { ["name"] = "Dravax' Schlüssel", ["text"] = "Questgegenstand\nBenutzen: Öffnet einen Käfig der Wellenskorn, um Sylara Schattenherz zu befreien.\n\"Dieser aufwendig gestaltete Schlüssel besteht aus Teufelseisen.\"" }
entries[136410] = { ["name"] = "Kalecs Abbildkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört für 30 Sek. ein Abbild von Kalec. (30 Sek. Abklingzeit)" }
entries[136412] = { ["name"] = "Robustes Rüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Machtstufe eines Champions um 5, bis hin zu Stufe 850.\nVerkaufspreis:" }
entries[136413] = { ["name"] = "Saat der Verderbnis", ["text"] = "Questgegenstand\n\"Ein Überrest der Verderbnis, die Cenarius befallen hatte.\"" }
entries[136414] = { ["name"] = "Fläschchen Mondbrunnenwasser", ["text"] = "Questgegenstand\nBenutzen: Trinkt aus dem Fläschchen, um in den Smaragdgrünen Traum überzugehen." }
entries[136419] = { ["name"] = "Notizbuch des Ausgräbers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht es einem Archäologen, bis zu einer maximalen potenziellen Fertigkeit von 800 Fragmente zu finden und Artefakte zu vervollständigen.\nBenötigt Archäologie (1)\n\"Lehrt Euch Archäologie der Verheerten Inseln.\"" }
