entries[136774] = { ["name"] = "Gefütterte Treter des Ruhms", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 80 / 80\n\"Für lange Wachen benötigt man weiche Schuhe.\"\nVerkaufspreis:" }
