entries[136777] = { ["name"] = "Kragen der ehrenhaften Preisung", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[136778] = { ["name"] = "Skovalds Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nEisen Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[136779] = { ["name"] = "Mächtiger Blutstein", ["text"] = "Questgegenstand\nBenutzen: Kanalisiert die Macht des Blutsteins. (4 Sek. Abklingzeit)\n\"Von brillanter Farbe und warm.\"" }
entries[136780] = { ["name"] = "Begleiterausbildungshandbuch: Tot spielen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt den Befehl 'Tot spielen'.\nEuer Begleiter stellt sich tot, sodass Gegner ihn ignorieren. Hält bis zu 6 Min. lang an.\nVerkaufspreis:" }
entries[136781] = { ["name"] = "Begleiterausbildungshandbuch: Hol' die Beute", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt den Befehl 'Hol' die Beute!'.\nBefiehlt Eurem Tier, die Beute von einem Leichnam innerhalb von 40 Metern aufzulesen.\nVerkaufspreis:" }
entries[136782] = { ["name"] = "Feuerwerkgebrauchsanweisung", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt Jäger die Fähigkeit 'Feuerwerk'.\nSchieß Feuerwerk von Eurem Gewehr, Bogen oder Eurer Armbrust ab.\nVerkaufspreis:" }
entries[136783] = { ["name"] = "Die Kunst der Verhüllung", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt Jäger die Fähigkeit 'Aspekt des Chamäleons'.\nDer Jäger nimmt die Aspekte eines Chamäleons an und kann nicht aufgespürt werden.\nVerkaufspreis:" }
entries[136784] = { ["name"] = "Ewigkeitssand", ["text"] = "Questgegenstand\n\"Verzauberter Sand aus den Hallen der Tapferkeit.\"" }
entries[136785] = { ["name"] = "Wertsachen aus dem Schattenmoor", ["text"] = "Questgegenstand\n\"Wertvolle Ressourcen und Erbstücke, die von den Bewohnern des Schattenmoors zurückgelassen wurden.\"" }
entries[136786] = { ["name"] = "Insigne der Ungekrönten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mitglieder der Ungekrönten tragen dieses Insigne stets bei sich. Sonst könnte man ja nicht beweisen, derjenige zu sein, für den man sich ausgibt.\"" }
entries[136787] = { ["name"] = "Foliant der Wildnis: Treantgestalt", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Druide\nBenutzen: Lehrt Druiden die Fähigkeit 'Treantgestalt'.\nVerwandelt Euch in die Gestalt eines Treants.\nVerkaufspreis:" }
entries[136789] = { ["name"] = "Foliant der Wildnis: Reittiergestalt", ["text"] = "Foliant der Wildnis: Reittiergestalt\nWird beim Aufheben gebunden\nKlassen: Druide\nBenutzen: Lehrt Druiden die Fähigkeit 'Reittiergestalt'.\nVerwandelt Euch in eine reitbare Reisegestalt, die Eure Bewegungsgeschwindigkeit um 40% erhöht. Beschützt Euch vor Verwandlungseffekten. Kann nur im Freien verwendet werden.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten.\nVerkaufspreis:" }
entries[136790] = { ["name"] = "Foliant der Wildnis: Wildtiere aufspüren", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Druide\nBenutzen: Lehrt Druiden die Fähigkeit 'Wildtiere aufspüren'.\nZeigt alle Wildtiere in der Nähe auf der Minikarte an.\nVerkaufspreis:" }
entries[136791] = { ["name"] = "Tagebuch der Meisterin, Teil 1", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Auszug aus dem Tagebuch der Meisterin.\"" }
entries[136792] = { ["name"] = "Tagebuch der Meisterin, Teil 2", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Auszug aus dem Tagebuch der Meisterin.\"" }
entries[136793] = { ["name"] = "Tagebuch der Meisterin, Teil 3", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Auszug aus dem Tagebuch der Meisterin.\"" }
entries[136794] = { ["name"] = "Foliant der Wildnis: Flattern", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Druide\nBenutzen: Lehrt Druiden die Fähigkeit 'Flattern'.\nIhr schlagt mit den Flügeln und verringert so Eure Fallgeschwindigkeit.\nVerkaufspreis:" }
entries[136795] = { ["name"] = "Foliant der Wildnis: Freund des Waldes", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Druide\nBenutzen: Lehrt Druiden die Fähigkeit 'Freund des Waldes'.\nSchließt Freundschaft mit einem Umgebungstier, das dem Druiden daraufhin 1 Stunde lang folgt.\nVerkaufspreis:" }
entries[136796] = { ["name"] = "Nekrotischer Foliant: Leichendetonation", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Todesritter\nBenutzen: Lehrt Todesritter die Fähigkeit 'Leichendetonation'.\nLässt ein Ziel in einem Regen aus Blut und Eingeweiden explodieren. Kann nicht auf die Überreste von mechanischen Einheiten oder Elementaren angewandt werden.\nVerkaufspreis:" }
entries[136797] = { ["name"] = "Magischer Foliant: Arkaner Linguist", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt Magier die Fähigkeit 'Arkaner Linguist'.\nIhr seid in der Lage, die Sprachen verbündeter Völker zu verstehen.\nVerkaufspreis:" }
entries[136799] = { ["name"] = "Magischer Foliant: Illusion", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt Magier die Fähigkeit 'Illusion'.\nVerwandelt das Aussehen des Magiers für 2 Min. in das eines andern Spielercharakters.\nVerkaufspreis:" }
entries[136800] = { ["name"] = "Meditationshandbuch: Zenflug", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Mönch\nBenutzen: Lehrt die Fähigkeit 'Zenflug'.\nIhr fliegt auf einer meditativen Wolke mit hoher Geschwindigkeit durch die Luft.\nVerkaufspreis:" }
entries[136801] = { ["name"] = "Göttlicher Foliant: Nachsinnen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Paladin\nBenutzen: Lehrt die Fähigkeit 'Nachsinnen'.\nGestattet Euch einen kurzen Moment des Friedens, den Ihr in stiller Kontemplation des Lichts verbringt.\nVerkaufspreis:" }
entries[136802] = { ["name"] = "Gefängniszellenschlüssel", ["text"] = "Die Schattenblutzitadelle\nWird beim Aufheben gebunden\nEinzigartig\n\"Schließt die Gefängnistüren der Schattenblutzitadelle auf.\"" }
entries[136803] = { ["name"] = "Schmutzige Tricks, Band 1: Aufdeckung", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Lehrt die Fähigkeit 'Aufdeckung'.\nVerkaufspreis:" }
entries[136804] = { ["name"] = "Götze der Wildnis", ["text"] = "Questgegenstand\n\"Das Relikt leuchtet mit ätherischer Energie.\"" }
entries[136806] = { ["name"] = "Glas Arkwein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Erhaltet 1 uraltes Mana.\nVerkaufspreis:" }
entries[136810] = { ["name"] = "Neuer Rekrut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Startet mich." }
entries[136811] = { ["name"] = "Fischpigmente", ["text"] = "Questgegenstand\n\"Gleichermaßen violett wie grau... und stinkend.\"" }
entries[136812] = { ["name"] = "Sabelitsulfat", ["text"] = "Questgegenstand\n\"Eine verfeinerte Version des Fels aus dem die Rabenwehr geschlagen wurde.\"" }
entries[136819] = { ["name"] = "Dragurstaub", ["text"] = "Questgegenstand\n\"Eine Kiste mit modrig riechendem Staub, der stark an Knochenstaub erinnert.\"" }
entries[136820] = { ["name"] = "Nythendras Herz", ["text"] = "Questgegenstand\n\"Das verderbte Herz des grünen Drachen Nythendra. Während die Verderbnis ihr äußeres Feuer erlöschen ließ, brennt ihr inneres Feuer noch immer so heiß wie die Sonne.\"" }
entries[136821] = { ["name"] = "Leypigmente", ["text"] = "Questgegenstand\n\"Ein glitzerndes, violettes Pigment, das für Tätowierungen verwendet werden kann.\"" }
entries[136822] = { ["name"] = "Gestohlenes Relikt von Nar'thalas", ["text"] = "Questgegenstand\n\"Von den Naga der Hassnattern aus den Ruinen von Nar'thalas gestohlen.\"" }
entries[136823] = { ["name"] = "Deucus' Leitungsverzeichnis", ["text"] = "Questgegenstand\n\"Eine Liste mit Zutaten und einer Bauanleitung für einen neuen Sudkatalysator.\"" }
entries[136825] = { ["name"] = "Glyphe 'Wildes Chamäleon'", ["text"] = "Klassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzengestalt annehmt, wird Eure verwandelte Gestalt zufällig ausgewählt.\nVerkaufspreis:" }
entries[136826] = { ["name"] = "Glyphe 'Herbstliches Wachstum'", ["text"] = "Klassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt Euer 'Blühendes Leben' zu einer üppigen Herbstblume aufblühen.\nVerkaufspreis:" }
entries[136827] = { ["name"] = "Yseras Traumtrank", ["text"] = "Questgegenstand\n\"Ein altes Nachtelfengebräu, von dem man sagt, dass es die Augen für eine unsichtbare Welt öffnet.\"" }
entries[136831] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Paladin\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[136832] = { ["name"] = "Unlesbare Schriften", ["text"] = "Questgegenstand\n\"Der auf diese Schriftrollen gekritzelte Text ist ohne Hilfe nicht zu entziffern.\"" }
entries[136833] = { ["name"] = "Seherkugel des Orakels", ["text"] = "Questgegenstand\n\"Das scheint die Kugel zu sein, die es dem Orakel gestattet, die Schriften der verlorenen Priesterinnen zu entziffern.\"" }
entries[136834] = { ["name"] = "Mächtiger Seelensplitter", ["text"] = "Questgegenstand\n\"Er spiegelt nicht das Gesicht des Betrachters wider, sondern das Gesicht der im Inneren gefangenen Seele.\"" }
entries[136835] = { ["name"] = "Blätter der Träumerträne", ["text"] = "Questgegenstand\nEinzigartig\n\"Blätter der Träumerträne, einer Pflanze, die nur selten in den Wäldern von Val'sharah vorkommt.\"" }
entries[136836] = { ["name"] = "Fläschchen der Nachtgeborenen", ["text"] = "Questgegenstand\nBenutzen: Mischt 5 Traumlaub und Blätter der Träumerträne, um Yseras Traumtrank herzustellen." }
entries[136838] = { ["name"] = "Intaktes Murlocauge", ["text"] = "Questgegenstand\n\"Nicht gerade die appetitlichste aller Garnituren.\"" }
entries[136839] = { ["name"] = "Ei von Gangamesh", ["text"] = "Questgegenstand\n\"Das würde ein sagenhaftes Omelett ergeben.\"" }
entries[136840] = { ["name"] = "Mylunes Flöte", ["text"] = "Questgegenstand\n\"Eine einfache Holzflöte.\"" }
entries[136843] = { ["name"] = "Akolythen der Schwarzen Ernte", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136844] = { ["name"] = "Rudel Wichtel", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136845] = { ["name"] = "Dämonen der Teufelswache", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136846] = { ["name"] = "Familiarstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Magier\nBenutzen: Zaubert einen Familiarstein herbei, der entweder einen arkanen, feurigen oder eisigen Familiar enthält. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[136849] = { ["name"] = "Leuchtfeuer der Natur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nKlassen: Druide\nBenutzen: Teleportiert Euch an einen naturbelassenen Ort. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[136850] = { ["name"] = "Gestohlener Leykristall", ["text"] = "Questgegenstand\n\"Es ist noch ein kleines bisschen Leyenergie darin vorhanden.\"" }
entries[136851] = { ["name"] = "Kommandantin Domitilles Helm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[136852] = { ["name"] = "Schlachtlieder", ["text"] = "Benutzen: Fügt \"Schlachtlieder\" Eurem akustischen Stimmungsverbesserer hinzu." }
entries[136854] = { ["name"] = "Arsenal: Bewaffnung des Draenorherausforderers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Sammelt die Vorlagen aller Waffen, die für das Erreichen einer Goldmedaille in allen Herausforderungsmodi von Warlords of Draenor gewährt werden.\nVerkaufspreis:" }
entries[136855] = { ["name"] = "Ruf des Jägers", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruft einen zufälligen Tierbegleiter herbei, der einen zufällig ausgewählten Jägeraspekt repräsentiert und Euch 15 Sek. lang folgt. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[136856] = { ["name"] = "Friedenshymnen", ["text"] = "Benutzen: Fügt \"Friedenshymnen\" Eurem akustischen Stimmungsverbesserer hinzu." }
entries[136857] = { ["name"] = "Lieder der Legion", ["text"] = "Benutzen: Fügt \"Lieder der Legion\" Eurem akustischen Stimmungsverbesserer hinzu." }
entries[136858] = { ["name"] = "Dunkler T'uure", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nHeilig Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\n\"Dieses Artefakt ist der Dunkelheit anheimgefallen.\"\nVerkaufspreis:" }
entries[136859] = { ["name"] = "Fette Bärenleber", ["text"] = "Questgegenstand\n\"Die sollte fettig genug für Irisse sein.\"" }
entries[136860] = { ["name"] = "Felsschwingenhippogryphenei", ["text"] = "Questgegenstand\n\"Sieht aus, als würdet Ihr einen Kriegshammer benötigen, um das zu öffnen.\"" }
