entries[136927] = { ["name"] = "Scharlachrotes Buch der Beichten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nKlassen: Priester\nBenutzen: Bringt ein befreundetes Ziel dazu, ein Geheimnis zu beichten.\n\nVielleicht ist es auch nur eine subtile Form der Gedankenkontrolle... (6 Sek. Abklingzeit)\n\"Die Scharlachroten haben wirklich ein Händchen dafür, die Wahrheit ans Tageslicht zu bringen.\"\nVerkaufspreis:" }
entries[136928] = { ["name"] = "Kugel des Thaumaturgen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nKlassen: Priester\nBenutzen: Die Kugel hebt Eure persönliche Affinität zu Licht oder Schatten hervor. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[136931] = { ["name"] = "Das Handbuch des meisterhaften Mahlens", ["text"] = "Questgegenstand\n\"Größtenteils eine Abhandlung über grundlegende Methoden, mit ein paar zusätzlichen Seiten, in denen sich der Autor mit automatisierten Mahlprozessen auseinandersetzt.\"" }
entries[136934] = { ["name"] = "Tobender Elementarstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schamane\nBenutzen: Beschwört einen zufälligen Feuer-, Wasser- oder Erdfamiliar. Familiare unterschiedlicher Typen neigen dazu, sich gegenseitig zu bekämpfen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[136935] = { ["name"] = "Kaulquappenwolkensaat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nKlassen: Schamane\nBenutzen: Ihr beschwört einen Regen aus Fröschen am Zielort. (45 Sek. Abklingzeit)\n\"Ein ernstzunehmendes Omen für einen Froschregen.\"\nVerkaufspreis:" }
entries[136936] = { ["name"] = "Wasserelementare", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[136937] = { ["name"] = "Vol'jins Schlangentotem", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schamane\nBenutzen: Beschwört einen von Vol'jins Schlangenzauberschutzen zu Füßen des Zaubernden, der 1 Min. lang wiederholt nahekommende Kleintiere innerhalb von 25 Metern angreift und mit 100 Feuerschaden überzieht. (20 Min Abklingzeit)\nVerkaufspreis:" }
entries[136938] = { ["name"] = "Foliant der Verhexung: Compy", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Compy'.\nVerwandelt den Gegner für 1 Min. in einen Compy. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
