entries[136968] = { ["name"] = "Sturmdrachenei", ["text"] = "Questgegenstand\n\"Blitze knistern über die Oberfläche der Schale.\"" }
entries[136969] = { ["name"] = "Foliant der Verhexung: Spinne", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Spinne'.\nVerwandelt den Gegner für 1 Min. in eine Spinne. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
entries[136970] = { ["name"] = "Maske des Spiegelbilds", ["text"] = "Questgegenstand\nBenutzen: Kopiert das Aussehen von Anarys Lunastre." }
entries[136971] = { ["name"] = "Foliant der Verhexung: Schlange", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Schlange'.\nVerwandelt den Gegner für 1 Min. in eine Schlange. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
entries[136972] = { ["name"] = "Foliant der Verhexung: Schabe", ["text"] = "Wird beim Anlegen gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Schabe'.\nVerwandelt den Gegner für 1 Min. in eine Kakerlake. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
entries[136973] = { ["name"] = "Bürde der Wachsamkeit", ["text"] = "Wird beim Aufheben gebunden\nLeben Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[136974] = { ["name"] = "Ermächtigung des Donners", ["text"] = "Wird beim Aufheben gebunden\nSturm Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[136975] = { ["name"] = "Hunger des Rudels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, wird Eure Geschwindigkeit 10 Sek. lang um 11 erhöht.\nVerkaufspreis:" }
entries[136976] = { ["name"] = "Etheldrins Brustplatte", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 165 / 165\nVerkaufspreis:" }
entries[136977] = { ["name"] = "Schattenfederschal", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 2 Vielseitigkeit\nVerkaufspreis:" }
entries[136978] = { ["name"] = "Funke der Nullifikation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n+ 7 Vielseitigkeit\nAnlegen: Beim Erleiden von Magieschaden besteht eine Chance, dass der Angreifer mit dem Effekt 'Erstickende Flammen' belegt wird, der ihn für 2 Sek. zum Schweigen bringt.\n\nDieser Effekt kann nur ein Mal alle 20 Sek. auftreten. (Procchance: 40%, 20s Abklingzeit)\nVerkaufspreis:" }
entries[136979] = { ["name"] = "Geschorene Manschetten der Fledermausbrut", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[136981] = { ["name"] = "Dämonenfoliant der Empyreumgesellschaft", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Ein teufelsgravierter Foliant voller dämonischer Zaubersprüche.\"" }
entries[136983] = { ["name"] = "Grabstaub", ["text"] = "Questgegenstand\n\"Vom Kummer der Verschiedenen erfüllt.\"" }
entries[136984] = { ["name"] = "Erhabener", ["text"] = "\"Ein mächtiger Erhabener, der Euch auf Missionen begleitet und so Eure Erfolgschancen stark erhöht.\"" }
entries[136985] = { ["name"] = "Dose mit überhitztem Öl", ["text"] = "Questgegenstand\n\"Das Öl ist so dunkel, dass man scheinbar in flüssige Leere starrt.\"" }
entries[136986] = { ["name"] = "Hirschblutprobe", ["text"] = "Questgegenstand\n\"Fühlt sich warm an.\"" }
entries[136987] = { ["name"] = "Gereifter Schneepflaumenbrandy", ["text"] = "Questgegenstand\n\"Vier Jahre gereift. Ein ausgezeichneter Jahrgang.\"" }
entries[137008] = { ["name"] = "Sturmfurordiamant", ["text"] = "Wird beim Aufheben gebunden\nSturm Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[137010] = { ["name"] = "Halb volle Flasche Arkwein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewinnt 50 uraltes Mana.\n\"Die andere Hälfte hat Thalyssra getrunken.\"" }
entries[137011] = { ["name"] = "Verkorkte Flasche", ["text"] = "Questgegenstand\n\"Ein Geschenk von Ly'leth an Thalyssra.\"" }
entries[137014] = { ["name"] = "Achor, der ewige Hunger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 200 / 200\nKlassen: Dämonenjäger\nAnlegen: 'Rachsüchtiger Rückzug' heilt Euch um 25% Eurer maximalen Gesundheit und gewährt Euch 8 Sek. lang 20% Lebensraub.\n\"Dämonenjäger stehen - was die Kampfeslust angeht - den Legionen ihres meistgehassten Feindes in nichts nach.\"\nVerkaufspreis:" }
entries[137015] = { ["name"] = "Ekogespenst, Erschaffer von Welten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 200 / 200\nKlassen: Druide\nAnlegen: Erhöht die Effekte von 'Dickes Fell', 'Astraler Einfluss', 'Schnelligkeit der Wildnis' und 'Yseras Gabe' um 75%.\n\"Wir konnten nicht nur das Gefühl eines eigenen Ortes, sondern tatsächlich einen solchen Ort selbst für uns erzeugen. Und alles, was jemals existiert hat, schwimmt auf der Oberfläche unseres Traums. Nun hört, was ich höre.\"\nVerkaufspreis:" }
entries[137016] = { ["name"] = "Sal'salabims verlorene Tunika", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Mönch\nAnlegen: Wenn Ihr 'Fasshieb' einsetzt, wird die verbleibende Abklingzeit von 'Feuerodem' abgeschlossen.\n\"Sal'salabim könnte das verloren haben, als er für sechs Stunden besinnungslos war...\"\nVerkaufspreis:" }
entries[137017] = { ["name"] = "Brustplatte der goldenen Val'kyr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\n+ 4 Vielseitigkeit\nHaltbarkeit 200 / 200\nKlassen: Paladin\nAnlegen: Durch jeden mit 'Schild des Rächers' getroffenen Gegner wird die verbleibende Abklingzeit von 'Wächter der Uralten Könige' um 3 Sek. verringert.\n\"Das Überbleibsel einer großen Kommandantin, die gleißend wie die Sonne aus dem Himmel auf ihre Feinde herabstieß.\"\nVerkaufspreis:" }
entries[137018] = { ["name"] = "Schicksalgeber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Krieger\nAnlegen: Abgefangene Angriffe gewähren Euch und dem Ziel Eurer Fähigkeit 'Abfangen' einen Absorptionsschild, der 10 Sek. lang Schaden in Höhe von 50% des vom Angreifer verursachten Schadens absorbiert.\n\"Unterwerft die Zeit selbst Eurem Willen, um die Welt vor der Zerstörung zu schützen.\"\nVerkaufspreis:" }
entries[137019] = { ["name"] = "Cenedril, Spiegel des Hasses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Mönch\nAnlegen: 'Karmaberührung' verursacht 150% mehr Schaden.\n\"Kennt Ihr den Feind und auch Euch selbst, gibt es keinen Grund, je wieder eine Schlacht zu fürchten.\"\nVerkaufspreis:" }
entries[137020] = { ["name"] = "Flüstern der Nathrezim", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nKlassen: Paladin\nAnlegen: 'Urteil des Templers' und 'Göttlicher Sturm' erhöhen den Schaden Eures nächsten Einsatzes von 'Urteil des Templers' oder 'Göttlicher Sturm' innerhalb von 4 Sek. um 15%.\n\"Erbärmlich... Mehr habt Ihr nicht zu bieten?\"\nVerkaufspreis:" }
entries[137021] = { ["name"] = "Die List des Schreckenslords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Schurke\nAnlegen: Meucheln, Gesetzlosigkeit\nErhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Dolchfächer' um 35%. Bis zu 30-mal stapelbar.\n\nTäuschung\nErhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Shurikensturm' um 25%. Bis zu 30-mal stapelbar.\n\"Ich habe Euch erwartet, junger Prinz. Ich bin Mal'Ganis. Wie Ihr sehen könnt, gehört Euer Volk jetzt mir.\"\nVerkaufspreis:" }
entries[137022] = { ["name"] = "Das Opfer von Loramus Thalipedes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Dämonenjäger\nAnlegen: 'Teufelsrausch' verursacht pro getroffenem Ziel 10% mehr Schaden.\n\"Nur diese Stiefel blieben übrig, als Rakh'likh durch das Steinmesser des Versiegelns im Körper von Loramus dem Entweihten eingekerkert wurde.\"\nVerkaufspreis:" }
entries[137023] = { ["name"] = "Versprechen Elunes, der Mondgöttin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\nAnlegen: 'Lunarschlag' und 'Solarzorn' verursachen 8% mehr Schaden und gewähren den Effekt 'Macht Elunes', der die Heilung Eures nächsten Einsatzes von 'Nachwachsen' um 30% erhöht und seine Zauberzeit um 5% verringert. Bis zu 20-mal stapelbar.\n\"Wenn andere Leben und Energie von Euch erhalten, schenke ich Euch dafür einen Teil meines Lebens und meiner Energie.\"\nVerkaufspreis:" }
entries[137024] = { ["name"] = "Feline Schleicher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\nAnlegen: Gewährt alle 15 Sek. eine Aufladung von 'Schnelligkeit des Raubtiers'. Außerdem ist die Fähigkeit jetzt bis zu 3-mal stapelbar.\n\"Es heißt, der Wahnsinn von Marl Wurmdorn hätte diese Stiefel mit Macht erfüllt.\"\nVerkaufspreis:" }
entries[137025] = { ["name"] = "Skysecs Trutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Druide\nAnlegen: 'Rasende Regeneration' heilt Euch im Verlauf von 3 Sek. um zusätzliche 12% Eurer maximalen Gesundheit.\n\"Während der Schlacht um den Hyjal widerstand Skysec, der Wächter von Nordrassil, endlosen Wellen der Geißel und der Legion. Am Ende gab er voller Stolz sein Leben für die Verteidigung des uralten Weltenbaums.\"\nVerkaufspreis:" }
entries[137026] = { ["name"] = "Essenz der Infusion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\nAnlegen: 'Gelassenheit' verursacht bei Zielen, deren Gesundheit unter 60% liegt, um 60% erhöhte Heilung.\n\"Fühlt, wie die Natur durch Eure Adern fließt.\"\nVerkaufspreis:" }
entries[137027] = { ["name"] = "Feuersteinläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\nAnlegen: Jeder von Eurem 'Feuerodem' getroffene Gegner verringert die Abklingzeit von 'Stärkendes Gebräu' um 2 Sek., bis zu einem Maximum von 6 Sek.\n\"Bruder Adam und Bruder David waren brillante Mathematiker und Mönche. Ständig plapperten sie von Abaki und Parabeln. - Braumeisterin Brynild\"\nVerkaufspreis:" }
entries[137028] = { ["name"] = "Ei'thas, Mondgleiter von Eramas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\nAnlegen: Erhöht die von 'Beleben' hervorgerufene Heilung um 10%.\nAnlegen: 'Erhebende Trance' erhöht die Heilung Eurer Fähigkeit 'Beleben' zusätzlich um 10% und lässt sie 1 zusätzliches Ziel heilen.\n\"Eramas Leuchtfeuer hat immer wieder erwähnt, wie bequem diese Prachtstücke sind.\"\nVerkaufspreis:" }
entries[137029] = { ["name"] = "Katsuos Finsternis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\nAnlegen: Verringert die Kosten von 'Furorfäuste' um 1 Chi.\n\"So sprach Kaulder zu seinem Bruder Katsuo: Mit der Zeit und durch langes Üben verbessern sich Eure Reflexe und Eure Fäuste schlagen härter zu, als Eure Gegner aushalten.\"\nVerkaufspreis:" }
entries[137030] = { ["name"] = "Fußpolster des Dämmergängers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\nAnlegen: Die verbleibende Abklingzeit von 'Vendetta' wird pro 65 verbrauchter Energie um 1 Sek. verringert.\n\"Wenn Euch eine SI:7-Agentin wie Caelvana ins Visier nimmt, solltet Ihr besser laufen. Schnell, sofort und so weit die Füße tragen.\"\nVerkaufspreis:" }
entries[137031] = { ["name"] = "Thraxis trickreiche Treter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\nAnlegen: 'Tötung' verursacht zusätzlichen Schaden in Höhe von 20% Eurer erhöhten Bewegungsgeschwindigkeit.\n\"Thraxi verkleidete sich oft als Braumeistermönch, um ihre Feinde zu täuschen.\"\nVerkaufspreis:" }
entries[137032] = { ["name"] = "Gang der Schattensatyrn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\nAnlegen: 'Schattenschlag' regeneriert 3 Energie und zusätzlich 1 Energie pro 3 Meter zwischen Euch und Eurem Ziel.\n\"Obwohl über die Entstehung der Schattensatyrn nichts Genaues bekannt ist, steht eine Tatsache fest: Es sind körperlose Kreaturen, die man nicht nur im Smaragdgrünen Alptraum antrifft, sondern auch auf Azeroth.\"\nVerkaufspreis:" }
entries[137033] = { ["name"] = "Ullrs Federschneeschuhe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Jäger\nAnlegen: Jeder Schaden verursachende Schuss verringert die verbleibende Abklingzeit von 'Volltreffer' um 0.8 Sek.\n\"Sie verliehen der Jägerin ein Gefühl der Schwerelosigkeit - eine Ruhe und Gleichmut inmitten des Sturms.\"\nVerkaufspreis:" }
entries[137034] = { ["name"] = "Nesingwarys Fallentreter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Jäger\nAnlegen: Wenn eine Eurer Fallen ausgelöst wird, werden 25 Fokus erzeugt.\n\"Etwas ziemlich Großes mit ebenso großen Zähnen wollte sich einen Happen von diesen Stiefeln abbeißen.\"\nVerkaufspreis:" }
entries[137035] = { ["name"] = "Der Blutpakt des Betrügers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schamane\nAnlegen: Es besteht eine Chance von 20%, dass 'Erdschock' den gesamten aufgezehrten Mahlstrom zurückerstattet. (Procchance: 20%)\n\"Ner'zhul, Schamanenältester vom Schattenmondklan, wollte sein Volk retten und sich endlich die Macht und den Respekt sichern, nach denen er sich immer gesehnt hatte. Doch er wurde betrogen...\"\nVerkaufspreis:" }
entries[137036] = { ["name"] = "Elementare Ausgleicher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Schamane\nAnlegen: Verbündete, die sich innerhalb des Effektbereichs Eures Zaubers 'Heilender Regen' aufhalten, erhalten 10% mehr Heilung durch Eure anderen Heilzauber.\n\"Ursprünglich wurden diese Prachtstücke von einer mächtigen Verdammniswache eingesetzt, um Feinde mit einem feurigen Regen zu vernichten. Später hat man sie als Ausgleich für die zuvor angerichtete Zerstörung einem edleren Zweck zugeführt.\"\nVerkaufspreis:" }
entries[137037] = { ["name"] = "Uvanimor, die Unschönheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Todesritter\nAnlegen: Nahkampfangriffe [ Schlickspucker : Eurer Monstrosität / Eures Ghuls] haben eine Chance von 10%, eine Eurer Runen zu aktivieren.\n\"Die verderbende Macht des Nachtbrunnens fließt durch diesen Ring, sodass sein Träger die Mächte aller anzapfen kann, die unter seinem Befehl stehen.\"\nVerkaufspreis:" }
entries[137038] = { ["name"] = "Zorn der Halbriesen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Tempowertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Dämonenjäger\nAnlegen: [ Dämonenklingen : 'Dämonenklingen' / 'Dämonenbiss'] erzeugt zusätzliche 1-14 Jähzorn.\n\"Diese überdimensionierten Vrykul sind sicherlich nicht die ersten Bewohner von Nordend, denen man über den Weg laufen will. Versucht es lieber mit den Untoten der boreanischen Tundra.\"\nVerkaufspreis:" }
entries[137039] = { ["name"] = "Makellose Teufelsessenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Druide\nAnlegen: Die verbleibende Abklingzeit von [ Inkarnation: Erwählter der Elune : 'Inkarnation: Erwählter der Elune' / 'Himmlische Ausrichtung'] wird pro 12 verbrauchter Astraler Macht um 1 Sek. verringert.\n\"Die Druiden des Smaragdkreises manipulierten die Teufelsenergie in diesem Stein, um ihren Einklang mit der Wildnis zu steigern.\"\nVerkaufspreis:" }
entries[137040] = { ["name"] = "Schillerndes Signet", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Druide\nAnlegen: Erhöht in Katzengestalt Eure Energieregeneration um 5% und Eure maximale Energie um 100.\n\"Das innere Feuer Leyaras hat dieses Signet verzaubert. Ihr spürt, dass sie endlich Frieden gefunden hat.\"\nVerkaufspreis:" }
entries[137041] = { ["name"] = "Doppelte Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Druide\nAnlegen: 'Überlebensinstinkte' erhält 1 zusätzliche Aufladung und wird 15% schneller wieder aufgeladen.\n\"Druiden der Klaue können sich verwandeln, um somit schneller oder zäher zu werden. Für gewöhnlich entscheiden sie sich für die zweite Variante.\"\nVerkaufspreis:" }
entries[137042] = { ["name"] = "Tränenstein der Elune", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Druide\nAnlegen: Durch Euren Zauber 'Wildwuchs' geheilte Verbündete erhalten eine Chance von 15%, um auch den Effekt 'Verjüngung' zu erhalten. (Procchance: 15%)\n\"Der sich um Elune, eine der wenigen wahren Gottheiten von Azeroth, rankende Mythos legt nahe, dass ihre wahre Identität noch immer nicht gänzlich erfasst wurde.\"\nVerkaufspreis:" }
entries[137043] = { ["name"] = "Frizzos Fingerfalle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Jäger\nAnlegen: Erhöht den Schaden von [ Schlachten : 'Schlachten' / 'Zerlegen'] um 10%.\nAnlegen: Wenn Ihr 'Zerlegen' gegen einen Gegner einsetzt, der von 'Aufschlitzen' betroffen ist, springt 'Aufschlitzen' auf 1 anderes Ziel über, das von 'Zerlegen' getroffen wurden.\n\"Mit etwas Butter geht die auch problemlos wieder ab.\"\nVerkaufspreis:" }
entries[137044] = { ["name"] = "Juwel der Verlorenen Abtei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Mönch\nAnlegen: Erhöht die Dauer der Staffelung um 3.0 Sek.\n\"Dieses Kleinod war ursprünglich ein Geschenk des Magiers Veri'thas, wurde aber angeblich nach einem Konflikt zwischen den Mönchen und den Elfen aus der Verlorenen Abtei gestohlen.\"\nVerkaufspreis:" }
entries[137045] = { ["name"] = "Auge von Collidus dem Sphärenwächter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Mönch\nAnlegen: Jedes Mal, wenn 'Beruhigender Nebel' heilt, wird die Absorptionsmenge Eures nächsten Einsatzes von 'Lebenskokon' um 3% erhöht. Bis zu 50-mal stapelbar.\n\"Zumindest eines seiner Augen.\"\nVerkaufspreis:" }
entries[137046] = { ["name"] = "Ilterendi, Kronjuwel von Silbermond", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Paladin\nAnlegen: 'Richturteil' erhöht Eure Heilung 5 Sek. lang um 15%.\n\"Silbermond wurde aus weißem Stein erbaut und mit karminroten Wandbehängen geschmückt. Aber die Stadt war nicht nur für ihre Schönheit bekannt, sondern auch als Zentrum magischer Ausbildung. Viele meisterliche Manipulatoren des Mana haben dort ihren Sitz.\"\nVerkaufspreis:" }
entries[137047] = { ["name"] = "Heathcliffs Unsterblichkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Paladin\nAnlegen: Während Ihr Euch im Effektbereich Eurer 'Weihe' aufhaltet, erleidet Ihr 4% weniger Schaden.\n\"Heathcliff, auch bekannt als Unsterbliches Objekt, war angeblich gegen jegliche schweren Wunden immun. Manche fragten sich, ob die Standhaftigkeit des Blutritters nicht sogar den Naturgesetzen der Welt selbst trotzte.\"\nVerkaufspreis:" }
entries[137048] = { ["name"] = "Liadrins entfesselter Zorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Paladin\nAnlegen: Während 'Zornige Vergeltung' aktiv ist, erhaltet Ihr alle 6 Sek. 1 Heilige Kraft.\n\"Wir wurden von dem Mann verraten, den wir unseren Prinzen nannten. Ich verpflichte die Klingen meiner Blutritter der Bezwingung Kil'jaedens und der Wiederherstellung Silbermonds. Wir werden an Eurer Seite kämpfen, A'dal.\"\nVerkaufspreis:" }
entries[137049] = { ["name"] = "Insigne von Rabenholdt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Tempowertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Schurke\nAnlegen: Eure Combopunkte erzeugenden Einzelzielangriffe fügen Zielen innerhalb von 15 Metern vor Euch 15% zusätzlichen Schaden als Schattenschaden zu.\n\"Dieses Insigne wird nur an jene verliehen, die sich als Meister über die Schatten erwiesen und im Dienste Rabenholdts getötet haben.\"\nVerkaufspreis:" }
entries[137050] = { ["name"] = "Auge des Wirbelnden Nethers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Schamane\nAnlegen: Wenn Ihr Gegnern mit Euren Feuer-, Frost- oder Naturzaubern Schaden zufügt, wird Euer verursachter Schaden 8 Sek. lang um 1.5% erhöht. Jedes weitere Element gewährt eine eigene Anwendung.\n\"Nirgends ist die Macht der Elemente stärker als im Nether - obwohl sie dort verzerrt und nur schwer als solche erkennbar sind.\"\nVerkaufspreis:" }
entries[137051] = { ["name"] = "Fokussierer von Jonat dem Ältesten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Tempowertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Schamane\nAnlegen: 'Welle der Heilung' und 'Heilende Woge' erhöht die Heilung Eures nächsten Einsatzes von 'Kettenheilung' um 10%. Dieser Effekt ist bis zu 5-mal stapelbar.\n\"Unter der Ausbildung von Jonat Han meisterten neue Schamanen des Drachenschinderklans die Künste des Wassers - um den einen sowie auch die vielen zu heilen.\"\nVerkaufspreis:" }
entries[137052] = { ["name"] = "Ayalas steinernes Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Krieger\nAnlegen: Eure Angriffe haben eine Chance, dass Euer nächster Einsatz von 'Hinrichten' keine Wut kostet und gegen jedes Ziel, ungeachtet seiner prozentualen Gesundheit, eingesetzt werden kann.\n\"In Valhalas streckte der Grubenkämpfer Ayala der Unerbittliche Feind um Feind nieder auf seinem Weg zum Legendentum. Je schwächer seine Gegner wurden, desto letaler wurde seine Präzision. Selbst wenn die Feinde ihn schon besiegt wähnten, hatte er immer ein Ass im Ärmel.\"\nVerkaufspreis:" }
entries[137053] = { ["name"] = "Kazzalax, Fujiedas Zorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Krieger\nAnlegen: 'Blutdurst' erhöht Euren verursachten Schaden und Eure erhaltene Heilung 10 Sek. lang um 1%. Bis zu 4-mal stapelbar.\n\"Die Jinyu erzählen von dem großen Krieger Fujieda, der viele Stunden in einem flachen Tümpel auf der Lauer lag, um einen mächtigen Teufelsdämon zu erschlagen.\"\nVerkaufspreis:" }
entries[137054] = { ["name"] = "Die Mauern fielen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Krieger\nAnlegen: 'Schildschlag' erzeugt 2 zusätzliche Wut und verringert die verbleibende Abklingzeit von 'Schildwall' um 4 Sek.\n\"Als inmitten des Dritten Krieges die Mauern der Verteidiger von Kalimdor zu Fall gebracht wurden, weigerte sich Shaka, das Urtum des Krieges, es ihnen gleichzutun.\"\nVerkaufspreis:" }
entries[137055] = { ["name"] = "Zevrims Hunger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Jäger\nAnlegen: Erhöht sämtlichen verursachten Schaden um 3%.\nAnlegen: 'Im Visier' hat eine Chance von 15%, 'Mal des Jägers' nicht zu entfernen.\n\"Diese Kraft wurde aus Jägern gewonnen, die in Düsterbruch geopfert wurden.\"\nVerkaufspreis:" }
entries[137056] = { ["name"] = "Luffawickel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: Erhöht Schaden und Reichweite von 'Hauen' um 25%.\n\"Es geht eben nichts über einen guten Luffaschwamm.\"\nVerkaufspreis:" }
entries[137057] = { ["name"] = "Verbotene Berührung des verborgenen Meisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: 'Berührung des Todes' verursacht 40% mehr Schaden und kann innerhalb von 5 Sek. ein zweites Mal eingesetzt werden, bevor die Abklingzeit ausgelöst wird.\n\"Uralte Erkenntnisse über die Einflussnahme auf den Fluss der Lebensenergie wurden über Jahrtausende im Geheimen von Meister zu Meister weitergegeben.\"\nVerkaufspreis:" }
entries[137058] = { ["name"] = "Gezeitenrufer des Prätorianers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: Erhöht die Dauer Eures Totems des heilenden Flusses, Eures Totems der Heilungsflut und Eures Totems der Geistverbindung um 20%.\n\"Um gemeinsam gegen Azeroths größte Feinde zu bestehen, trafen sich die größten Denker zu einem Forum, das der intellektuellen Diskussion aller Probleme und der strategischen Planung gewidmet war, während ihre Champions an der Front kämpften.\"\nVerkaufspreis:" }
entries[137059] = { ["name"] = "Tyrs Hand des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Paladin\nAnlegen: Verringert die Abklingzeit von 'Handauflegung' um 70%.\n\"Nachdem er durch den riesigen Protodrachen Galakrond seine Hand verloren hatte, fertigte Jotun eine neue für Tyr.\"\nVerkaufspreis:" }
entries[137060] = { ["name"] = "Archavons schwere Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Krieger\nAnlegen: Verringert die Wutkosten von 'Tödlicher Stoß' um 8.\n\"Tief unten in der von Tausendwinter geschützten Kammer lauerte Archavon der Steinwächter voller Hass auf alle Eindringlinge.\"\nVerkaufspreis:" }
entries[137061] = { ["name"] = "Raddons Kaskadenblick", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\nAnlegen: Die verbleibende Abklingzeit von 'Augenstrahl' wird pro getroffenem Gegner um 0.3 Sek. verringert, bis maximal um 20 Sek.\n\"Die Welt... zieht vorbei... und wir bestehen in Ewigkeit.\"\nVerkaufspreis:" }
entries[137062] = { ["name"] = "Der Smaragdgrüne Traumfänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: 'Sternensog' verringert 5 Sek. lang die benötigte Astrale Macht für 'Sternensog' um 5. Bis zu 2-mal stapelbar.\n\"Ysera träumt und die Welt erbebt.\"\nVerkaufspreis:" }
entries[137063] = { ["name"] = "Der Blick für das Wesentliche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Mönch\nAnlegen: 'Zenmeditation' klingt 50% schneller ab und wird nicht mehr durch Bewegung oder erlittene Nahkampftreffer abgebrochen.\n\"Lehnt Euch zurück, entspannt Euch und nehmt die Welt um Euch wahr.\"\nVerkaufspreis:" }
entries[137064] = { ["name"] = "Voodoomaske des Schattenjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Kette\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Jäger\nAnlegen: 'Totstellen' heilt Euch bei Aktivierung um 20% Eurer maximalen Gesundheit und danach 10 Sek. lang pro Sekunde um zusätzliche 5% Eurer maximalen Gesundheit, solange Ihr Euch weiter totstellt.\n\"Wenn die mich kalt machen wollen, dann besser richtig und beim ersten Versuch. Am besten, wenn ich schlafe. - Vol'jin nach dem missglückten Mordversuch durch Garrosh.\"\nVerkaufspreis:" }
entries[137065] = { ["name"] = "Blick der Gerechtigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: Wenn das Ziel mehr als 75% Gesundheit hat, verursacht 'Hammer der Gerechtigkeit' 204% Heiligschaden, erzeugt 1 Heilige Kraft und die Abklingzeit ist um 75% verringert.\n\"Dieser Helm schützte einst das Haupt von Hochlord Alexandros Mograine und wäre - wären die Dinge anders verlaufen - wohl als Erbstück an seine Söhne Renault und Darion Mograine gegangen.\"\nVerkaufspreis:" }
entries[137066] = { ["name"] = "Umhang der Teufelsflammen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\n+ 2 Vielseitigkeit\nKlassen: Dämonenjäger\nAnlegen: Ihr erleidet 15% weniger Magieschaden, solange 'Feuerbrandaura' aktiv ist.\n\"Obwohl er so aussieht wie all die anderen Exemplare, die man in den geschmolzenen Tiefen findet, scheint dieses Prachtstück etwas intensiver zu brennen.\"\nVerkaufspreis:" }
entries[137067] = { ["name"] = "Elizes ewigwährende Einhüllung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Leder\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Druide\nAnlegen: 'Hauen' kann bis zu 2 zusätzliche Male gestapelt werden.\n\"Während der Zerschlagung war '100% naturbelassene Wut' eine zutreffende Beschreibung des Besitzers.\"\nVerkaufspreis:" }
entries[137068] = { ["name"] = "Gamaschen der Schwarzen Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Leder\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Mönch\nAnlegen: 'Donnerfokustee' gewährt 1 zufällige zusätzliche Aufladung von 'Überschwang', 'Einhüllender Nebel', 'Essenzborn', 'Erneuernder Nebel' oder 'Beleben'.\n\"Seien es seltene Artefakte, Gladiatorenkämpfe oder lukratives Glücksspiel, die Schwarze Flamme hat sich darauf spezialisiert, nur die besten Dienstleistungen und Unterhaltungsmöglichkeiten anzubieten, die für Geld zu haben sind.\"\nVerkaufspreis:" }
entries[137069] = { ["name"] = "Valeeras Wille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Leder\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 145 / 145\nKlassen: Schurke\nAnlegen: 'Finte' heilt Euch im Verlauf von 5 Sek. um 20% Eurer maximalen Gesundheit.\n\"In jungen Jahren überlebte Valeera den Tod ihrer Eltern, ihre Gefangennahme und die Sklaverei. All ihre Feinde unterschätzten stets ihren Überlebenswillen.\"\nVerkaufspreis:" }
entries[137070] = { ["name"] = "Tyelca, Statur von Ferren Marcus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Paladin\nAnlegen: 'Schild des Rächers' verursacht 20% mehr Schaden und springt auf 2 zusätzliche Ziele über.\n\"Macht erwächst aus Stärke und wahre Stärke erwächst aus kräftigen Beinen, die Euch wie Wurzeln auf dem Boden verankern.\"\nVerkaufspreis:" }
entries[137071] = { ["name"] = "Schulterstücke des Runenmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\nAnlegen: 'Metamorphose' schließt die Abklingzeit von all Euren Zeichen ab. Gewährt Euch außerdem eine Aufladung von 'Dämonenstachel'.\n\"Molgeim von der Versammlung des Eisens verstand es, Runen für ein gewaltiges Arsenal zerstörerischer Effekte einzusetzen.\"\nVerkaufspreis:" }
entries[137072] = { ["name"] = "Aman'thuls Weisheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: Wenn 'Verjüngung' ein Ziel heilt, das bei voller Gesundheit ist, wird die Dauer um 3 Sek. erhöht, bis zu einer maximalen Erhöhung von 9 Sek. pro Einsatz.\n\"Ihr seid mit der großen Aufgabe betraut worden, die Reinheit der Zeit aufrechtzuerhalten. Wisst, dass es nur eine wahre Zeitlinie geben kann, auch wenn es jene gibt, die nach anderem trachten. Ihr müsst sie bewahren.\"\nVerkaufspreis:" }
entries[137073] = { ["name"] = "Schiftung des Einklangs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Mönch\nAnlegen: 'Beruhigender Nebel' heilt einen zweiten verletzten Verbündeten innerhalb von 15 Metern um 50% der ursprünglichen Menge.\n\"All die Orte, die Ihr Euch je vorgestellt habt - sie sind alle real. Es ist eine fiktive Stadt in Eurem Geist, und Ihr kennt jedes Haus und jede Gasse. Euer Verstand ist eine Welt. Jeder von uns ist ein Ort.\"\nVerkaufspreis:" }
entries[137074] = { ["name"] = "Echos der Großen Zerschlagung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Kette\n8 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Schamane\nAnlegen: 'Erdschock' gewährt je nach verbrauchtem Mahlstrom eine Chance von bis zu 50%, dass Euer nächster Einsatz von 'Erdbeben' kostenlos ist und 100% mehr Schaden verursacht.\n\"Der Brunnen der Ewigkeit implodierte vor 10.000 Jahren, doch die Auswirkungen spürt man selbst heute noch.\"\nVerkaufspreis:" }
entries[137075] = { ["name"] = "Tak'theritrix' Schulterpolster", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\nAnlegen: 'Dunkle Transformation' verstärkt auch [ Dunkle Richterin : Eure Dunkle Richterin / Euren Gargoyle] und 'Armee der Toten' 30 Sek. lang und erhöht ihren Schaden um 40%.\n\"Im Verlauf der ersten Invasion von Azeroth spielte der Legionskommandant Tak'theritrix eine Schlüsselrolle bei der Auslöschung der ersten Verteidigungslinie der Nachtelfen.\"\nVerkaufspreis:" }
entries[137076] = { ["name"] = "Obsidiansteinschiftung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: 30% der auf Euch gewirkten Heilung, wird zusätzlich gleichmäßig auf alle Ziele aufgeteilt, die unter dem Effekt Eurer 'Flammen' stehen.\n\"Von diesem Rüstungsteil geht dieselbe Macht aus wie vom Dunklen Portal.\"\nVerkaufspreis:" }
entries[137077] = { ["name"] = "Gewicht der Erde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Krieger\nAnlegen: Der Effektradius von 'Heldenhafter Sprung' ist um 100% erhöht und davon getroffene Gegner werden zusätzlich mit 'Kolossales Schmettern' belegt.\n\"Alle lebenden Kreaturen vertrauen in die Ruhe der Erde. Sie wissen nichts von den Strömen, die sich unter ihrer Oberfläche bewegen. Sie verstehen ihr Gewicht nicht. Sie können ihre Macht nicht verstehen.\"\nVerkaufspreis:" }
entries[137078] = { ["name"] = "Der Rat des Dunklen Titanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: Erhöht die Endheilung von 'Blühendes Leben' um 200%. Die regelmäßige Heilung von 'Blühendes Leben' hat eine Chance von 5%, so viel Gesundheit wiederherzustellen wie die Endheilung.\n\"Habt Geduld. Ihr seid noch jung, aber eines Tages bekommt Ihr, was Euch zusteht.\"\nVerkaufspreis:" }
entries[137079] = { ["name"] = "Gai Plins lindernde Schärpe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: 'Reinigendes Gebräu' heilt Euch sofort um 25% des entfernten gestaffelten Schadens.\n\"Gai Plin extrahierte die heilenden Kräfte des Ru'shanflusses und durchtränkte damit diesen Gürtel.\"\nVerkaufspreis:" }
entries[137080] = { ["name"] = "Brüllen der sieben Löwen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\nAnlegen: 'Zorn des Wildtiers' verringert die Fokuskosten all Eurer Fähigkeiten um 15%.\n\"Tyven, Schildwache der Nachtelfen, fertigte diesen Gürtel aus den Mähnen der legendären sieben Löwen.\"\nVerkaufspreis:" }
entries[137081] = { ["name"] = "Kriegsgürtel der Schildwachenarmee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\nAnlegen: Der Schaden Eures nächsten Einsatzes von 'Gezielter Schuss' wird für jeden Gegner, den Ihr mit 'Mehrfachschuss' trefft, um 10% erhöht, bis zu einem Maximum von 20 Treffern.\n\"Schildwachen sind die Meisterschützen und Elitekämpfer der Nachtelfen. Nur wenige Krieger können mit der Geschwindigkeit und Gerissenheit der stolzen Bogenschützinnen mithalten.\"\nVerkaufspreis:" }
entries[137082] = { ["name"] = "Helgischt, Strick des Nebelmarodeurs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\nAnlegen: Euer verursachter Schaden gegen das erste von 'Harpune' getroffene Ziel wird für 10 Sek. um bis zu 30% erhöht, basierend auf Eurer Entfernung zum Ziel.\n\"Ein geisterhaftes Heulen schallt durch die Nebel, noch lange nachdem Helheim sein nächstes Opfer gefordert hat.\"\nVerkaufspreis:" }
entries[137083] = { ["name"] = "Makelloser Protoschuppengurt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: 'Lavaeruption' verursacht im Verlauf von 6 Sek. zusätzlich (13.5% der Zaubermacht) Schaden. Bis zu 5-mal stapelbar.\n\"Wurde aus der Schuppe eines riesigen Protodrachen gefertigt, die uralt aussieht, sich aber immer noch heiß anfühlt.\"\nVerkaufspreis:" }
entries[137084] = { ["name"] = "Akainus absolute Gerechtigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: Wenn Eure Waffen sowohl mit 'Flammenzunge' als auch 'Frostbrand' verzaubert sind, verursacht 'Lavapeitsche' 50% mehr Schaden.\n\"Seine geschmolzene Macht vermochte ganze Landstriche zu formen.\"\nVerkaufspreis:" }
entries[137085] = { ["name"] = "Intakte Nazjatarhaut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: Wenn Ihr 'Springflut' auf ein Ziel mit weniger als 40% Gesundheit wirkt, wird die Abklingzeit des Zaubers sofort abgeschlossen.\n\"Die Naga von Nazjatar sind Meister der Magie und leben in den Tiefen des Ozeans. Es ist also nicht verwunderlich, dass diejenigen, die eine ihrer abgestreiften Häute tragen, mehr Gewalt über die Gezeiten erhalten.\"\nVerkaufspreis:" }
entries[137086] = { ["name"] = "Thrayns Kette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Paladin\nAnlegen: Heilig\n'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 25% und den verursachten Schaden um zusätzlich 10%.\n\nSchutz\n'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 50% und den verursachten Schaden um zusätzlich 10%.\n\nVergeltung\n'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 50% und den verursachten Schaden um zusätzlich 10%.\n\"Das Gebet eines uralten Champions aus den Hallen der Tapferkeit erklingt durch diese Glieder: Wer mit dem Licht ist, ist niemals allein.\"\nVerkaufspreis:" }
entries[137087] = { ["name"] = "Naj'entus' Rückgrat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Krieger\nAnlegen: Wenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen.\n\"Nur wenige Naga waren so stark wie Naj'entus, der Champion von Lady Vashj und Diener von Illidan Sturmgrimm.\"\nVerkaufspreis:" }
entries[137088] = { ["name"] = "Stürmer von Ceann-Ar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Krieger\nAnlegen: Jedes Mal, wenn Ihr in einen Wutzustand verfallt, erhaltet Ihr 8 Wut.\n\"Legendäre Kämpfer stellen sich ihren Gegnern immer Auge in Auge.\"\nVerkaufspreis:" }
entries[137089] = { ["name"] = "Wucht des Donnergotts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 3 Vielseitigkeit\nHaltbarkeit 70 / 70\nKlassen: Krieger\nAnlegen: Für jeden von 'Donnerknall' getroffenen Gegner wird die verbleibende Abklingzeit von 'Demoralisierender Ruf' um 3 Sek. verringert.\n\"Und der Gott des Donners strafte die Unfolgsamen mit großem Zorn und furchtbarer Rache...\"\nVerkaufspreis:" }
entries[137090] = { ["name"] = "Bionische Stabilisatoren der Mo'arg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Dämonenjäger\nAnlegen: 'Gleve werfen' verursacht pro getroffenem Gegner 25% mehr Schaden.\n\"Wenn Ihr eine Säge stabilisieren könnt, könnt Ihr auch eine Gleve stabilisieren.\"\nVerkaufspreis:" }
entries[137091] = { ["name"] = "Verlorene Unterarmschienen des Entweihers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\n+ 3 Vermeidung\nHaltbarkeit 70 / 70\nKlassen: Dämonenjäger\nAnlegen: 'Seelenspalter' verringert die Abklingzeit eines zufälligen Zeichens um 8 Sek. (500ms Abklingzeit)\n\"Während der Schlacht mit Loramus Thalipedes auf der Anhöhe des Entweihers wurden diese Unterarmschienen von Razelikhs Gelenken gerissen und in Richtung des Dunklen Portals geschleudert.\"\nVerkaufspreis:" }
entries[137092] = { ["name"] = "Oneths Intuition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: 'Sternensog' und 'Sternenregen' haben eine Chance von 20%, den jeweils anderen Zauber kostenlos zu machen. (Procchance: 20%)\n\"Aglaya hätte es wohl Oneths Vermessenheit genannt.\"\nVerkaufspreis:" }
entries[137094] = { ["name"] = "Die Umklammerung des Wildformers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: Kritische Treffer Eurer Blutungseffekte haben eine Chance von 30%, 'Urfuror' auszulösen. (Procchance: 30%)\n\"Die verderbten Druiden der Wildhufe hofften, eines Tages die Macht zu erlangen, die Alzzin diesen Prachtstücken verlieh.\"\nVerkaufspreis:" }
entries[137095] = { ["name"] = "Edraith, Bindungen von Aglaya", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: 'Rasche Heilung' verlängert die Dauer Eurer aktiven regelmäßigen Heilungseffekte auf dem Ziel um 10 Sek.\n\"Aus dem Balg eines uralten Bullen hergestellt, der mit ewiger Glückseligkeit gesegnet war.\"\nVerkaufspreis:" }
entries[137096] = { ["name"] = "Petrichorgeschenk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: Jedes Wirken von 'Erneuernder Nebel' verringert die verbleibende Abklingzeit von 'Belebung' um 2.0 Sek.\n\"Ah... es riecht heute nach Regen.\"\nVerkaufspreis:" }
entries[137097] = { ["name"] = "Trinkhorndeckel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: Die Dauer von 'Sturm, Erde und Feuer' wird pro verbrauchtem Chi um 0.4 Sek. erhöht. (100ms Abklingzeit)\n\"Die hartgesottenen Vrykul Nordends vermochten jeglichem Wetter zu widerstehen, solange sie nur genug zu trinken hatten.\"\nVerkaufspreis:" }
entries[137098] = { ["name"] = "Trainingsfesseln der Familie Zoldyck", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\nAnlegen: Eure Gifte und Blutungseffekte fügen Zielen mit weniger als 30% Gesundheit 30% mehr Schaden zu.\n\"Die Mitglieder der Familie Zoldyck werden von Geburt an in der Kunst des Meuchelns geschult. In den Kellergewölben ihres Anwesens werden sie gelehrt, tödlichste Gifte zu nutzen und ihnen zu widerstehen.\"\nVerkaufspreis:" }
entries[137099] = { ["name"] = "Grünhauts durchnässte Handfesseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schurke\nAnlegen: 'Zwischen die Augen' hat eine Chance von 20% pro Combopunkt, den Schaden Eures nächsten Einsatzes von 'Pistolenschuss' um 200% zu erhöhen.\n\"In einer gesetzlosen Welt voller Tavernenschlägereien und spontaner Duelle ist Treffsicherheit oberstes Gebot.\"\nVerkaufspreis:" }
entries[137100] = { ["name"] = "Leugnung der Halbriesen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\nAnlegen: Eure Finishing-Moves erhöhen die Dauer von 'Schattenklingen' pro verbrauchtem Combopunkt um 0.2 Sek.\n\"Wenn Ihr glaubt, ein Tauren, der sich im Schatten verstecken will, wäre ein lächerlicher Anblick, solltet Ihr einmal sehen, wie diese Vrykulhalbriesen am helllichten Tag durch die Gegend schleichen!\"\nVerkaufspreis:" }
entries[137101] = { ["name"] = "Ruf der Wildnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Jäger\nAnlegen: Verringert die Abklingzeit aller Aspekte um 35%.\n\"Jäger haben eine machtvolle Verbindung zur Wildnis: die Fähigkeit, Tieraspekte herbeizurufen, um sich selbst erstarken zu lassen und mit den wildesten Kreaturen anzufreunden.\"\nVerkaufspreis:" }
entries[137102] = { ["name"] = "Al'Akirs Verbitterung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: 'Kettenblitzschlag' fügt jedem weiteren Ziel 5% mehr Schaden zu.\n\"Blitze fahren immer noch durch diese Fesseln. Eure Macht scheint unendlich zu sein und immer weiter anzuwachsen...\"\nVerkaufspreis:" }
entries[137103] = { ["name"] = "Sturmböen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: Gegner, die von Eurem 'Sturmschlag' getroffen wurden, sind für 15 Sek. elektrisch geladen und versetzen einem Gegner in der Nähe alle 1 Sek. einen Schlag in Höhe von 5% Naturschaden.\n\"Diese aus den Schuppen eines uralten Sturmdrachen hergestellte Bindung entfesselt unkontrollierbare magische Energien gegen alles in der näheren Umgebung.\"\nVerkaufspreis:" }
entries[137104] = { ["name"] = "Nobundos Erlösung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: 'Kettenheilung' verringert die Manakosten Eures nächsten Einsatzes von 'Heilende Woge' um 50%.\n\"Scharfseher Nobundo hat die Stadt als Zerschlagener verlassen, doch kehrte er mit der Macht der Elemente zurück.\"\nVerkaufspreis:" }
entries[137105] = { ["name"] = "Uthers Schutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Paladin\nAnlegen: Erhöht die Dauer Eurer Fähigkeiten 'Segen der Freiheit' [ Segen der Aufopferung : 'Segen der Aufopferung' ] und [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] um 50%. Außerdem heilen sie das Ziel um 15% seiner maximalen Gesundheit.\n\"Uther der Lichtbringer, Anführer der Silbernen Hand, hatte solch eine Ausstrahlung auf dem Schlachtfeld, dass seine Ritter zuweilen gleichermaßen unbezwingbar und unaufhaltbar schienen.\"\nVerkaufspreis:" }
entries[137107] = { ["name"] = "Mannoroths Aderlassfesseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Krieger\nAnlegen: Ihr werdet pro 10 verbrauchter Wut um 1% Eurer maximalen Gesundheit geheilt.\n\"Kommt und trinkt von meinem Blut, auf dass Ihr Euch schon bald am Blut Eurer Feinde laben könnt.\"\nVerkaufspreis:" }
entries[137108] = { ["name"] = "Kakushans Sturmschuppenstulpen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Krieger\nAnlegen: [ Verwüster : Eure automatischen Angriffe erhöhen / 'Verwüsten' erhöht] den verursachten Schaden und die erzeugte Wut Eures nächsten Einsatzes von 'Schildschlag' oder 'Donnerknall' um 20%.\n\"Der große Krieger Kakushan fertigte sie aus den Häuten von Sturmschuppennaga, nachdem er und Ivagont ihre Dörfer an der Dunkelküste verwüstet hatten. Während die Naga voller Entsetzen flohen, tranken die Vrykul das Blut ihrer Stammesbrüder.\"\nVerkaufspreis:" }
entries[137109] = { ["name"] = "X'anshi, Schleier von Erzbischof Benedictus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Priester\nAnlegen: Wenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\n\"Ist es möglich, ohne jeden Akt des Verrats seine Ziele zu erreichen?\"\nVerkaufspreis:" }
