entries[137173] = { ["name"] = "Rekrutiererin Tianji", ["text"] = "\"Rekrutiererin Tianji kommt in den Tempel der Fünf Sonnenaufgänge und ermöglicht es Euch, Ochseninitianden zu rekrutieren, die Eure Champions auf Missionen begleiten.\"" }
entries[137178] = { ["name"] = "Verzauberte Knallfrösche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Auf den Boden werfen! (1 Min Abklingzeit)\n\"Eine mit Mana durchwirkte Kette Knallfrösche.\"\nVerkaufspreis:" }
entries[137179] = { ["name"] = "Groteskes Ettinleder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dicker als Drachenleder und halb so biegsam.\"" }
entries[137182] = { ["name"] = "Krone des Vergessenen Königs", ["text"] = "Questgegenstand\n\"Diese einfache, aber handwerklich anspruchsvolle Krone wurde einst von König Svergan Sturmmantel getragen. Das eingetrocknete Blut lässt auf ein gewaltsames Ableben schließen.\"" }
entries[137183] = { ["name"] = "Sturmmantelsignet", ["text"] = "Questgegenstand\n\"Das Signet des Sturmmantelklans.\"" }
entries[137184] = { ["name"] = "Medaillon des Drachenreiters", ["text"] = "Questgegenstand\n\"Ein strahlender Edelstein im Medaillon wird von den Schwingen eines Sturmdrachen eingerahmt.\"" }
entries[137185] = { ["name"] = "Rune der Herrschaft", ["text"] = "Questgegenstand\n\"Ein verzauberter, von Teufelsenergie erfüllter Runenstein.\"" }
entries[137186] = { ["name"] = "Kiste mit Verzauberungspergament", ["text"] = "Questgegenstand\n\"Eine Kiste mit Pergamenten verschiedenster Verzauberungen.\"" }
entries[137187] = { ["name"] = "Teufelsseelentinte", ["text"] = "Questgegenstand\n\"Eine Phiole mit dämonischer Tinte.\"" }
entries[137188] = { ["name"] = "Glyphe 'Feuriger Retter'", ["text"] = "Klassen: Krieger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Einschreiten' hinterlässt eine Feuerspur. Wenn man schon einschreitet, warum dann nicht mit Stil?\nVerkaufspreis:" }
entries[137189] = { ["name"] = "Satyrhorn", ["text"] = "Questgegenstand\nBenutzen: Durchbohrt ein Totem der Schattenteufel mit dem Satyrhorn, um es zu zerstören. 5 Meter Radius. (5 Sek. Abklingzeit)" }
entries[137190] = { ["name"] = "Rune des Öffnens", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine teufelsgravierte Rune.\"" }
entries[137191] = { ["name"] = "Glyphe 'Auge des Inquisitors'", ["text"] = "Klassen: Hexenmeister\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euer Auge von Kilrogg in ein Auge des Inquisitors.\nVerkaufspreis:" }
entries[137193] = { ["name"] = "Verstärkter Bernsteinkristall", ["text"] = "Questgegenstand\n\"Ein verstärkter Kristallbrocken, der dem Körper eines wütenden Bernsteinsplitters entnommen wurde.\"" }
entries[137194] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Jäger\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[137195] = { ["name"] = "Hochbergrüstung", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Rüstung, die einst von einem Verteidiger des Hochbergs getragen wurde.\"" }
entries[137196] = { ["name"] = "Donnerstaub", ["text"] = "Questgegenstand\n\"Magisch angereicherter Staub, der verwendet wird, um die Rüstungen des Donnertotemstamms zu verzaubern.\"" }
entries[137198] = { ["name"] = "Braumeisterausrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wühlt Euch durch die Braumeisterausrüstung, um eine zufällige Belohnung zu erhalten." }
