entries[137206] = { ["name"] = "Golganneths Gezeitenstein", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Stücke des Gezeitensteins wurden von Königin Azshara zusammengefügt. Bringt ihn zu Aegwynns Kammer in Dalaran.\"" }
entries[137207] = { ["name"] = "Verstärktes Rüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Machtstufe eines Champions um 10, bis hin zu Stufe 850.\nVerkaufspreis:" }
entries[137208] = { ["name"] = "Unzerstörbares Rüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Machtstufe eines Champions um 15, bis hin zu Stufe 850.\nVerkaufspreis:" }
entries[137209] = { ["name"] = "Rüstungsverbesserungsmarke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erschafft eine ungewöhnliche, seltene oder epische Rüstungsverbesserung für Champions." }
entries[137210] = { ["name"] = "Ein Schreiben von Erzmagier Vargoth", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit Teufelsmagie versiegelt.\"" }
entries[137211] = { ["name"] = "Nalamyas Buch der Verzauberungen", ["text"] = "Questgegenstand\n\"Ein Buch aus Borke und Blättern mit Feensymbolen auf den Seiten.\"" }
entries[137212] = { ["name"] = "Geschliffener Himmelsstein", ["text"] = "Questgegenstand\n\"Eignet sich zum Einsetzen in einen Ring.\"" }
entries[137213] = { ["name"] = "Rabenstaub", ["text"] = "Questgegenstand\n\"Tiefschwarzer Staub, der durch das Entzaubern von Siegeln der Nachtelfen der Rabenwehr entstanden ist.\"" }
entries[137214] = { ["name"] = "Geschliffener Tiefenbernstein", ["text"] = "Questgegenstand\n\"Eignet sich zum Einsetzen in einen Ring.\"" }
entries[137215] = { ["name"] = "Geschliffener Azsunit", ["text"] = "Questgegenstand\n\"Eignet sich zum Einsetzen in einen Ring.\"" }
entries[137220] = { ["name"] = "Marsch der Legion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Mönch\nAnlegen: 'Windlaufen' erhöht die Bewegungsgeschwindigkeit um zusätzliche 15%.\n\"Von seinem Platz auf Kil'jaedens Thron erhob Verdammnislord Kazzak sein Schwert und hieß die Dämonenarmee, in den Krieg zu ziehen.\"\nVerkaufspreis:" }
entries[137221] = { ["name"] = "Verzaubertes Rabensiegel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein verzaubertes Siegel, das mit dem Wappen von Lord Rabenkrone geziert wird.\"" }
entries[137222] = { ["name"] = "Blutrote Phiole", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Blutrote Phiole (3)\nBenutzen: Trinkt ein alchemistisches Gemisch, das Euch im Verlauf von 6 Sek. um 30% Eurer maximalen Gesundheit heilt. (5 Min Abklingzeit)" }
entries[137223] = { ["name"] = "Siegel der Nekrofantasie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Todesritter\nAnlegen: [ Hungernde Runenwaffe : 'Hungernde Runenwaffe' / 'Runenwaffe verstärken'] erhält 1 zusätzliche Aufladung und lädt sich 10% schneller wieder auf.\n\"Dunkles Flüstern aus dem Wirbelnden Nether lässt vermuten, dass dieses Siegel vor dem Dritten Krieg von den Nathrezim geschmiedet und dann einem der mächtigsten Leutnants der Geißel verliehen wurde.\"\nVerkaufspreis:" }
entries[137225] = { ["name"] = "Donnerzorn, Gesegnete Klinge des Windsuchers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+1 Beweglichkeit\n+1 Ausdauer\n+1 Feuerwiderstand\n+1 Naturwiderstand\nVerkaufspreis:" }
entries[137226] = { ["name"] = "Trupp Ochsenadepten", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[137227] = { ["name"] = "Qa'pla, Kriegsbefehl der Eredar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 95 / 95\nKlassen: Jäger\nAnlegen: 'Stachelpfeil' verringert die verbleibende Abklingzeit von 'Tötungsbefehl' um 3 Sek.\n\"Mit diesem Todesstoß werden wir die Sieger sein.\"\nVerkaufspreis:" }
entries[137235] = { ["name"] = "Tigrids Arkhana", ["text"] = "Questgegenstand\n\"Eine sehr alte Tasche mit Arkhana. Sieht jedoch noch brauchbar aus.\"" }
entries[137238] = { ["name"] = "Glyphe 'Dreizack'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Harpune' zeigt einen Dreizack anstelle Eurer angelegten Waffe an. Exklusiv mit: Glyphe 'Haken'\nVerkaufspreis:" }
entries[137239] = { ["name"] = "Glyphe 'Haken'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Harpune' zeigt einen Greifhaken anstelle Eurer angelegten Waffe an. Exklusiv mit: Glyphe 'Dreizack'\nVerkaufspreis:" }
entries[137240] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Jäger\nVerkaufspreis:" }
entries[137246] = { ["name"] = "Rückgrat von Thal'kiel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Hexenmeister\n\"Die Schreie des Erweckers hallten über Argus. Sie stellen eine düstere Erinnerung an den Preis dar, den er dafür zahlen musste, sich mit Dämonen eingelassen zu haben.\"\nVerkaufspreis:" }
entries[137247] = { ["name"] = "Trupp Tigeradepten", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[137248] = { ["name"] = "Hirogebräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 2 std. (Realzeit)\nBenutzen: Regeneriert 20 Sek. lang alle 2 Sek. 10% Gesundheit des Nutzers." }
entries[137249] = { ["name"] = "Glyphe 'Arachnophobie'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden öfter Spinnen herbeigerufen. Warum? Weil einfach jeder Angst vor Spinnen hat. Exklusiv mit: Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\nVerkaufspreis:" }
entries[137250] = { ["name"] = "Glyphe 'Nesingwarys Nemesis'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden oft Wildtiere herbeigerufen, die für gewöhnlich Opfer des berühmten Jägers sind. Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\nVerkaufspreis:" }
entries[137251] = { ["name"] = "Jia Nummer Neun", ["text"] = "\"Jia Nummer Neun kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
entries[137261] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Jäger\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[137267] = { ["name"] = "Glyphe 'Goblinisches Antigravitationsleuchtfeuer'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTauscht Eure Leuchtfeuer gegen goblinische Antigravitationsleuchtfeuer! Sie funktionieren sogar fast, und immerhin explodieren sie nicht. Exklusiv mit: Glyphe 'Sterneneruption'\nVerkaufspreis:" }
entries[137268] = { ["name"] = "Fragment von Xavius", ["text"] = "Questgegenstand\n\"Es wird Xavius sicher schwächen, diesen Teil seiner Seele zu verlieren.\"" }
entries[137269] = { ["name"] = "Glyphe 'Sterneneruption'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verschießt nun eine Sterneneruption, um den Zielort zu beleuchten. Exklusiv mit: Glyphe 'Goblinisches Antigravitationsleuchtfeuer'\nVerkaufspreis:" }
