entries[137273] = { ["name"] = "Runenfragment der Empyreumgesellschaft", ["text"] = "Questgegenstand\nEinzigartig (3)\nBenutzen: Fügt die Runenfragmente der Empyreumgesellschaft zu einer Teufelsrune der Empyreumgesellschaft zusammen. (3 Sek. Abklingzeit)\n\"Ein seltsam leuchtendes Steinfragment.\"" }
