entries[137276] = { ["name"] = "N'ero, Band der Versprechen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Priester\nAnlegen: Wenn 'Sühne' einem Gegner Schaden zufügt, heilt der Zauber jetzt auch Verbündete, die von Eurem 'Machtwort: Barriere' betroffen sind.\n\"Sie fühlen sich noch immer so an mich vergeudet an.\"\nVerkaufspreis:" }
