entries[137537] = { ["name"] = "Tirathons Verrat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nBenutzen: Stärkt Euch mit dunkler Energie, durch die Eure Angriffe eine Chance haben, zusätzlich 19 Schattenschaden zu verursachen und Euch einen Schild zu gewähren, der 21 Schaden absorbiert.\n\nHält 15 Sek. lang an. (1 Min, 15 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[137538] = { ["name"] = "Kugel der Qual", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Schwächt für 20 Sek. die Seele Eures Ziels, wodurch Ihr um 50% Eures dem Ziel zugefügten Schadens geheilt werdet, bis zu einer Gesamtheilung von 3008 Gesundheit. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[137539] = { ["name"] = "Fehlerhafte Gegenmaßnahme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Hüllt Eure Waffen für 30 Sek. in Eis, durch das Eure Nahkampfangriffe eine Chance haben, zusätzlich 45 Frostschaden zu verursachen und die Bewegungsgeschwindigkeit des Ziels für 8 Sek. um 20% zu verringern. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[137540] = { ["name"] = "Konkave Reflexionslinse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Heilzauber haben eine Chance, den Effekt 'Impuls' auf Euer Ziel abzufeuern, der es um 52 Gesundheilt heilt und auf bis zu 3 zusätzliche Ziele überspringt.\nVerkaufspreis:" }
entries[137541] = { ["name"] = "Monderleuchtetes Prisma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Erhöht Eure Beweglichkeit oder Intelligenz für 20 Sek. um 1 . Eure Distanzangriffe und Zauber rufen weitere Stapel dieses Effekts hervor. Bis zu 20-mal stapelbar. (400ms Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
