entries[137570] = { ["name"] = "Blutfangkokon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Blutzahnwitwe beschwört.\nBeschwört einen reitbare Blutfangwitwe oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Von ihren langen, gezackten Extremitäten tropft das Blut ihrer Feinde und/oder ihres Männchens.\"\nVerkäufer:\nDer verrückte Händler" }
entries[137571] = { ["name"] = "Erzmagier Vargoths Notizen", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein brandneues Notizbuch mit dem Titel 'Der Seelenstein der Nachtgeborenen'.\"" }
entries[137572] = { ["name"] = "Zoargs Kopf", ["text"] = "Questgegenstand\n\"Ohne seine zweite Reihe messerscharfer Zähne könnte man diesen Dämon nicht von anderen Teufelshunden unterscheiden.\"" }
entries[137573] = { ["name"] = "Llothienstreuner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Llothienstreuner beschwört.\nBeschwört Euren Llothienstreuner oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese geschmeidigen Füchse können trotz ihrer Größe geräuschlos über frisch gefallene Blätter streifen.\"\nQuest:\nDer scheue Volpin\nZone:\nSuramar" }
entries[137574] = { ["name"] = "Lebender Höllenkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Teufelsfeuerhöllenbestie beschwört.\nTeufelsfeuerhöllenbestie : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Die Illidari konnten eine dieser wilden Bestien zähmen, um sie als unaufhaltbares, furchtloses Reittier gegen die Legion einzusetzen.\"\nBeute von:\nGul'dan\nZone:\nDie Nachtfestung" }
entries[137575] = { ["name"] = "Dämonischer Höllenfeuerkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Höllenfeuerbestie beschwört.\nBeschwört Eure Höllenfeuerbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Aus den Tiefen des Nethers wird eine Kreatur heraufbeschworen, die aus purem Hass besteht und danach trachtet, alles Leben auf ihrem Wege auszulöschen.\"\nBeute von:\nGul'dan (Mythisch)\nZone:\nDie Nachtfestung" }
entries[137576] = { ["name"] = "Schwach leuchtender Kaltflammenkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Kaltflammenhöllenbestie beschwört.\nBeschwört Eure Kaltflammenhöllenbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die eigenartigen, eisigen Flammen lassen Euch gleichzeitig schwitzen und frieren.\"\nHandelsposten" }
entries[137577] = { ["name"] = "Räuberischer Blutstarrer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nRäuberischer Blutstarrer : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die schiere Menge an rohen roten Beeren, die diese Allesfresser verschlingen, verleiht ihnen ihre bemerkenswerte Augenfarbe.\"\nQuest:\nBlutstarrerwiedersehen" }
entries[137578] = { ["name"] = "Schneefederreißer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nSchneefederreißer : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Tiere können sich unter einer Nebelbank verstecken, bis sich die Beute nähert, und dann herausspringen und das Opfer mit einem einzigen Krallenhieb aufschlitzen.\"\nQuest:\nSchneefederwiedersehen" }
entries[137579] = { ["name"] = "Prächtiger Düsterschnabel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nPrächtiger Düsterschnabel : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die schimmernde Haut dieser ebenso wilden wie koordiniert agierenden Bestien dient dazu, ihre Beute zu verwirren und orientierungslos zu machen.\"\nQuest:\nDüsterschnabelwiedersehen" }
entries[137580] = { ["name"] = "Viridianscharfkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nViridianscharfkralle : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ihrer Tarnungsfähigkeiten können sie sich in magischen Wäldern, wie man sie beispielsweise auf den Verheerten Inseln findet, perfekt an die Umgebung anpassen.\"\nQuest:\nScharfkrallenwiedersehen" }
entries[137582] = { ["name"] = "Aschenbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n9 - 17 Schaden Geschwindigkeit 3.60\n(3.6 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\n\nHeilig Artefakt Relikt Slot\nFeuer Artefakt Relikt Slot\nBenutzen: Lässt den Aschenbringer in weitem Bogen herumwirbeln, fügt allen Gegnern innerhalb von 12 Metern vor Euch (174.3% der Angriffskraft)% Strahlenschaden zu und verringert ihre Bewegungsgeschwindigkeit für 6 Sek. um 50%.\n\nWenn Dämonen und Untote von 'Aschewelle' getroffen werden, werden sie für 6 Sek. betäubt.\n\"Klinge des Scharlachroten Hochlords\"" }
entries[137589] = { ["name"] = "Uniform der Empyreumgesellschaft", ["text"] = "Questgegenstand\nBenutzen: Lässt Kultisten glauben, dass Ihr ein Rekrut der Empyreumgesellschaft seid. Wirkt nur bei den Kultisten in der Enklave der Empyreumgesellschaft in Azsuna.\n\"Bestickt mit dem Insigne der Empyreumgesellschaft.\"" }
entries[137590] = { ["name"] = "Haufen Seide", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Shal'doreiseide. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137591] = { ["name"] = "Haufen Häute", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Steinbalgleder und Sturmschuppen. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137592] = { ["name"] = "Haufen Erz", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Leysteine und Teufelsschiefer. Kann auch zähflüssiges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137593] = { ["name"] = "Kräuterhaufen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Kräuter von den Verheerten Inseln. Kann auch schwarzes Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137594] = { ["name"] = "Haufen Juwelen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Edelsteine. Kann auch öliges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137595] = { ["name"] = "Zähflüssiges Transmutagen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\nVerkaufspreis:" }
entries[137596] = { ["name"] = "Schwarzes Transmutagen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\nVerkaufspreis:" }
entries[137597] = { ["name"] = "Öliges Transmutagen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\nVerkaufspreis:" }
entries[137598] = { ["name"] = "Perle der arkanen Weisheit", ["text"] = "Questgegenstand\n\"Arkane Energie dringt in blitzartigen Impulsen tief aus ihrem Inneren hervor.\"" }
entries[137599] = { ["name"] = "Pulsierender Sack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen (Realzeit)\n\"Eine zuckende Masse aus transmutiertem Fleisch.\"" }
entries[137600] = { ["name"] = "Haufen Hosen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Hosen. Kann auch öliges Transmutagen enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[137601] = { ["name"] = "Stapel Briefe", ["text"] = "Questgegenstand" }
entries[137604] = { ["name"] = "Instabiler Rissstein", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Zertrümmert den Stein und fügt bis zu 3 Gegnern innerhalb von 5 Metern 6 Sek. lang pro Sekunde 25 Schaden zu. (1 Min Abklingzeit)\n\"Wechselt schnell zwischen dieser Realität und einer anderen hin und her.\"" }
entries[137605] = { ["name"] = "Pläne: Leysteinstiefel", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Leysteinstiefel herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung von Leysteinstiefeln.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\nLeysteinstiefel\nWird beim Anlegen gebunden\nFüße Platte\n11 Rüstung\n+4 [Stärke oder Intelligenz]\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nBenötigt Leysteinerz (12), Fuchsblumenfluxus (2)\nOptionale Reagenzien: [] (#48)" }
entries[137606] = { ["name"] = "Pläne: Leysteinstulpen", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Leysteinstulpen herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung von Leysteinstulpen.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\nLeysteinstulpen\nWird beim Anlegen gebunden\nHände Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nHaltbarkeit 50 / 50\nVerkaufspreis:\nBenötigt Leysteinerz (12), Fuchsblumenfluxus (3)\nOptionale Reagenzien: [] (#48)" }
entries[137607] = { ["name"] = "Pläne: Leysteinhelm", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Leysteinhelm herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Leysteinhelms.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\nLeysteinhelm\nWird beim Anlegen gebunden\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Leysteinerz (16), Fuchsblumenfluxus\nOptionale Reagenzien: [] (#49)" }
entries[137608] = { ["name"] = "Knurrender Sack", ["text"] = "Wird beim Aufheben gebunden\n\"Offenbar bewegt sich darin etwas...\"\n<Zum Öffnen rechtsklicken>" }
entries[137609] = { ["name"] = "Holz", ["text"] = "Wird beim Aufheben gebunden\n\"Leicht brennbare, getrocknete Baumstämme.\"" }
entries[137610] = { ["name"] = "Intaktes Großhirschgeweih", ["text"] = "Questgegenstand" }
entries[137611] = { ["name"] = "Makellose Adlerschwanzfeder", ["text"] = "Questgegenstand" }
entries[137612] = { ["name"] = "Rohes Fleisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Der Verzehr von nicht durchgebratenem Fleisch kann eine Vergiftung hervorrufen.\n\"Dieses mit Fett durchzogene, erstklassige Stück Fleisch könnte ein tolles Steak ergeben, wenn man es ordentlich zubereitet.\"" }
entries[137613] = { ["name"] = "Herzhaftes Steak", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt beim Verzehr reichliche Sättigung.\n\"Dieses perfekt gebratene Steak bietet einen hohen Nährwert.\"" }
entries[137614] = { ["name"] = "Beißender Frostsplitterkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Frostsplitterhöllenbestie beschwört.\nBeschwört Eure Frostsplitterhöllenbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese eisigen Diener kommen aus einer unbekannten Dimension, die weit von dieser entfernt liegt.\"\nErfolg:\nWir werden einen größeren Stall brauchen\nKategorie:\nReittiere" }
entries[137615] = { ["name"] = "Geschmolzener Feuerkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Feuerkernhöllenbestie beschwört.\nFeuerkernhöllenbestie : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Legion hat Tausende andere Planeten erobert und nimmt, wenn sie sich mit extremen Bedingungen konfrontiert sieht, teuflische Änderungen an ihren Kriegsmaschinen vor.\"\nHandelsposten" }
entries[137616] = { ["name"] = "Emalons geladener Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Kette\n12 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 200 / 200\nKlassen: Schamane\nAnlegen: Wenn 'Tobende Blitze' mindestens 3 Ziele treffen, ist Euer verursachter Schaden 10 Sek. lang um 10% erhöht.\n\"Tief unten in der von Tausendwinter geschützten Kammer hielt Emalon der Sturmwächter mit eisernem Willen Wache.\"\nVerkaufspreis:" }
entries[137617] = { ["name"] = "Notizen des Forschers", ["text"] = "Questgegenstand\n\"Eine eng geschnürte Schriftrolle mit handgeschriebenen Notizen.\"" }
entries[137618] = { ["name"] = "Bergbeeren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt beim Verzehr minimale Sättigung.\n\"Farbenfrohe Früchte, die am Hochberg wachsen und nur wenig Nährwert bieten.\"" }
entries[137620] = { ["name"] = "Neqistiasamenkapseln", ["text"] = "Questgegenstand\nBenutzen: Spuckt einen Mundvoll Wasser aus." }
entries[137621] = { ["name"] = "Grimoire der Verdammten", ["text"] = "Questgegenstand\n\"Das Tagebuch von Erzlich Kel'Thuzad, das er während seiner Zeit in Naxxramas geführt hat.\"" }
entries[137622] = { ["name"] = "Wichtel im Glas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Befreit den gefangenen Wichtel. Er verspricht Euch seine Treue!\n\"Sieht etwas vollgestopft aus da drin.\"" }
entries[137623] = { ["name"] = "Amulett der Befehlsgewalt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Erhebt das Amulett der Befehlsgewalt und unterwerft einen Dämon vorübergehend Eurem Willen." }
entries[137624] = { ["name"] = "Schwarzmarktdiamant", ["text"] = "Questgegenstand\nBenutzen: Schleift den Diamanten zu Diamantdietrichen." }
entries[137625] = { ["name"] = "Diamantdietrich", ["text"] = "Questgegenstand\nVerkaufspreis:" }
entries[137626] = { ["name"] = "Teufelssognetzdrüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Erzeugt ein klebriges Netz." }
entries[137627] = { ["name"] = "Makelloser Kampfstein", ["text"] = "Benutzen: Wertet ein Kampfhaustier eines beliebigen Typs sofort zu epischer Qualität auf.\nVerkaufspreis:" }
entries[137628] = { ["name"] = "Weiches Sonnenrennerleder", ["text"] = "Questgegenstand\n\"Fühlt sich weich an und ist dennoch unfassbar stabil.\"" }
entries[137636] = { ["name"] = "Bewaffnung der ersten Generation", ["text"] = "\"Früher einmal war dies die sprichwörtliche Krone der Schöpfung, doch diese Zeiten sind vorbei.\"\nVerkaufspreis:" }
entries[137637] = { ["name"] = "Brüchige Waffen", ["text"] = "\"Diese Waffen wurden zu lange gelagert und würden wohl keine Schlacht mehr überstehen.\"\nVerkaufspreis:" }
entries[137638] = { ["name"] = "Teufelsverderbte Uniform", ["text"] = "\"Diese Uniform lag wohl zu lange in der Nähe einer Teufelsenergiequelle und sollte auf keinen Fall mehr getragen werden.\"\nVerkaufspreis:" }
entries[137639] = { ["name"] = "Frostversehrte Waffen", ["text"] = "\"Nach langer Zeit in klirrender Kälte wurden diese Waffen extrem brüchig, als sie auf wärmeren Schlachtfeldern zum Einsatz kamen.\"\nVerkaufspreis:" }
entries[137640] = { ["name"] = "Schimmelüberzogene Waffen", ["text"] = "\"Diese Waffen waren lange einem warmen und feuchten Klima ausgesetzt und sind nun von Schleim und Schimmel überzogen.\"\nVerkaufspreis:" }
entries[137641] = { ["name"] = "Verrostende Waffen", ["text"] = "\"Das Metall der Eisernen Horde vor Ort hat sich leider als kein besonders haltbares Material für Waffen erwiesen.\"\nVerkaufspreis:" }
entries[137642] = { ["name"] = "Ehrenabzeichen", ["text"] = "Wird an Kriegsmeute gebunden\n\"Kann bei PvP-Händlern gegen Waffen und Rüstung vergangener Zeit eingetauscht werden.\"\nVerkaufspreis:" }
entries[137643] = { ["name"] = "Alte Sense", ["text"] = "\"Sie war wohl Teil eines Paars, aber das bessere Exemplar fehlt.\"\nVerkaufspreis:" }
entries[137644] = { ["name"] = "Verwesendes Herz", ["text"] = "\"Sieht gar nicht aus wie das Herz eines Bären. Woher es wohl kommt?\"\nVerkaufspreis:" }
entries[137648] = { ["name"] = "Schlüpfriges Gebräu", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Schlüpfriges Gebräu (2)\nBenutzen: Befreit Euch von Bewegungsunfähigkeits-, Betäubungs-, Furcht- und Entsetzenseffekten und verringert die Dauer von zukünftigen Effekten dieser Art 6 Sek. lang um 60%. (5 Min Abklingzeit)" }
entries[137649] = { ["name"] = "Hammer von Khaz'goroth", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Hammer von Khaz'goroth befindet sich nicht länger im Besitz von Dargrul dem Unterkönig. Bringt ihn zu Aegwynns Kammer in Dalaran.\"" }
entries[137650] = { ["name"] = "Eimer mit blauer Farbe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versieht einen Haufen Kolossteile und Rußschmieds Energiekern mit Farbe.\nVerkaufspreis:" }
entries[137651] = { ["name"] = "Eimer mit graublauer Farbe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versieht einen Haufen Kolossteile und Rußschmieds Energiekern mit Farbe.\nVerkaufspreis:" }
entries[137652] = { ["name"] = "Eimer mit grüner Farbe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versieht einen Haufen Kolossteile und Rußschmieds Energiekern mit Farbe.\nVerkaufspreis:" }
entries[137653] = { ["name"] = "Eimer mit grauer Farbe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versieht einen Haufen Kolossteile und Rußschmieds Energiekern mit Farbe.\nVerkaufspreis:" }
entries[137654] = { ["name"] = "Haufen Kolossteile", ["text"] = "Wird beim Aufheben gebunden\n\"Braucht einen neuen Anstrich.\"\nVerkaufspreis:" }
entries[137655] = { ["name"] = "Deaktivierter grauer Koloss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen dunkelgrauen Koloss." }
entries[137656] = { ["name"] = "Deaktivierter blauer Koloss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen kobaltblauen Koloss." }
entries[137657] = { ["name"] = "Deaktivierter türkisfarbener Koloss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen türkisfarbenen Koloss." }
entries[137658] = { ["name"] = "Deaktivierter grüner Koloss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen tiefgrünen Koloss." }
entries[137659] = { ["name"] = "Rostiger Schlüssel", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Teufelsmagie verleiht ihm ein schwaches Leuchten.\"" }
entries[137660] = { ["name"] = "Die Silberne Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+22 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\n\nHeilig Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\nBenutzen: Entfesselt Euer inneres Licht, heilt 5 verletzte Verbündete sofort und heilt 20 Sek. lang alle 1 Sek. einen verletzten Verbündeten innerhalb von 40 Metern um (35.1% der Zaubermacht) Gesundheit.\n\nGeheilte Verbündete erhalten außerdem 12 Sek. lang 12% mehr Heilung durch Eure Zauber 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock'. (1 Min, 30 Sek. Abklingzeit)\n\"All dies war niemals unsere Absicht. Jetzt... jetzt steht diese junge Welt vor dem Untergang.\"" }
entries[137661] = { ["name"] = "Der Wahrheitshüter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n52 Rüstung\n+2 Stärke\n+7 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nHeilig Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\nBenutzen: Entfesselt einen blendenden Lichtblitz aus dem Wahrheitshüter , der allen Gegnern innerhalb von 8 Metern (56.7% der Angriffskraft) Heiligschaden zufügt und den Schaden, den sie Euch zufügen, 9 Sek. lang um 25% verringert. (1 Min Abklingzeit)\n\"Dieser Schild wird Lokens Lügen und Verrat ans Licht bringen. Ich wünschte, ich könnte bei Euch bleiben und Euch in diesem Krieg zur Seite stehen.\"" }
entries[137663] = { ["name"] = "Weiches Schaumstoffschwert", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verwundet einen Gegner trivialer Schwierigkeit tödlich.\nVerkaufspreis:" }
entries[137676] = { ["name"] = "Verschlüsselte Nachricht", ["text"] = "Questgegenstand\n\"Ohne eine Art Code kann man die Worte nicht entschlüsseln.\"" }
entries[137677] = { ["name"] = "Teufelsblut", ["text"] = "Questgegenstand\n\"Es gibt nur wenig auf dieser Welt, das noch widerwärtiger ist.\"" }
entries[137678] = { ["name"] = "Dämonischer Codeschlüssel", ["text"] = "Questgegenstand\n\"Wird verwendet, um Nachrichten zu entschlüsseln, die die Mitglieder der Verschleierten Hand sich untereinander schicken.\"" }
entries[137680] = { ["name"] = "Pläne: Leysteinbeinschützer", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Leysteinbeinschützer herstellt.\nVerringert die erforderlichen Materialien zur Herstellung von Leysteinbeinschützern.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\nLeysteinbeinschützer\nWird beim Anlegen gebunden\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Leysteinerz (24), Fuchsblumenfluxus (2)\nOptionale Reagenzien: [] (#49)" }
entries[137681] = { ["name"] = "Muster: Bluttotemsatteldecke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Bluttotemsatteldecke herstellt.\nStellt eine seidengewebte Satteldecke her.\nBenötigt Schneiderei der Verheerten Inseln (100)\n\nBluttotemsatteldecke\nBenutzen: Platziert eine Satteldecke auf Eurem Reittier, durch die das Reiten für 2 Stunden weitaus komfortabler wird.\n\nDie Dauer dieses Effekts ist für Schneider vervierfacht.\nBenötigt Shal'doreiseide (25)" }
entries[137686] = { ["name"] = "Stahlgebundenes Geschirr", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen stahlgebundenen Verschlinger beschwört.\nStahlgebundener Verschlinger: beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die stärksten Ketten können diese Bestie im Zaum halten.\"\nBeruf:\nSchmiedekunst" }
entries[137687] = { ["name"] = "Pläne: Teufelskernhundharnisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Teufelskernhundharnisch herstellt.\nStellt einen Teufelskernhundharnisch her.\nBenötigt Schmiedekunst der Verheerten Inseln (100)\nStahlgebundenes Geschirr\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen stahlgebundenen Verschlinger beschwört.\nStahlgebundener Verschlinger: beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die stärksten Ketten können diese Bestie im Zaum halten.\"\nBeruf:\nSchmiedekunstBenötigt Dämonenstahlbarren (100), Blut von Sargeras (50), Infernoschwefel (10), Teufelsbalg (10)" }
entries[137690] = { ["name"] = "Blutopfer", ["text"] = "Questgegenstand\nBenutzen: Bringt das dämonische Blutopfer dar, um das Ritual abzuschließen und mit der Seele von Illidan Sturmgrimm Verbindung aufzunehmen. (15 Sek. Abklingzeit)" }
entries[137691] = { ["name"] = "Bauplan: Intradalaranischer Wurmlochgenerator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen intradalaranischen Wurmlochgenerator herstellt.\nStellt einen intradalaranischen Wurmlochgenerator her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nIntradalaranischer Wurmlochgenerator\nBenutzen: Teleportiert Euch an einen bis zu 90 Meter entfernten Punkt. Kann nur in Dalaran verwendet werden.\nVerkaufspreis:\nBenötigt Leysteinerz (150), Chaosblaster , Teufelswurz (3)" }
entries[137692] = { ["name"] = "Bauplan: Blingtron-Schaltplandesignanleitung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Blingtron-Schaltplandesignanleitung herstellt.\nStellt eine Blingtron-Schaltplandesignanleitung her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBlingtron-Schaltplandesignanleitung\nSpielzeug\nBenutzen: Spielt ein Kabelentwirrungsspiel.\nVerkaufspreis:\nBenötigt Leysteinerz (50), Teufelsschiefer (50), Infernoschwefel (5)" }
entries[137693] = { ["name"] = "Bauplan: Reaves-Modul: Fehlschlagdetektormodus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Reaves-Modul: Fehlschlagdetektormodus herstellt.\nStellt ein Reaves-Modul: Fehlschlagdetektormodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nReaves-Modul: Fehlschlagdetektormodus\nBenutzen: Lehrt Reaves, den Fehlschlagdetektormodus zu aktivieren.\nVerkaufspreis:\nBenötigt Teufelsschiefer (80), Anti-Höllenbestien-Raketenwerfer (2)" }
entries[137694] = { ["name"] = "Bauplan: Reaves-Modul: Reparaturmodus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Reaves-Modul: Reparaturmodus herstellt.\nStellt ein Reaves-Modul: Reparaturmodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nReaves-Modul: Reparaturmodus\nBenutzen: Lehrt Reaves, den Reparaturmodus zu aktivieren.\nVerkaufspreis:\nBenötigt Teufelsschiefer (80), Automatikhammer (5)" }
entries[137695] = { ["name"] = "Bauplan: Reaves-Modul: Wurmlochgeneratormodus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Reaves-Modul: Wurmlochgeneratormodus herstellt.\nStellt ein Reaves-Modul: Wurmlochgeneratormodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nReaves-Modul: Wurmlochgeneratormodus\nBenutzen: Lehrt Reaves, den Wurmlochgeneratormodus zu aktivieren.\nVerkaufspreis:\nBenötigt Teufelsschiefer (80), Fehlschlagdetektorpylon (2), Infernoschwefel" }
entries[137697] = { ["name"] = "Bauplan: Blinzelabzugkopfkanone", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Blinzelabzugkopfkanone herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Blinzelabzugkopfkanone.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBlinzelabzugkopfkanone\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 85 / 85\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBenötigt Shal'doreiseide (40), Scharfschützenzielfernrohr (2), Lockerer Abzug (2), Repetierer des \"Wirbeligen Äthers\"\nOptionale Reagenzien: [] (#47)" }
