entries[137705] = { ["name"] = "Bauplan: Stationärer Kugelspender", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen stationären Kugelspender herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines stationären Kugelspenders.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nStationärer Kugelspender\nBenutzen: Stellt einen Geschützturm auf, der Euch im Kampf unterstützt. (2 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBenötigt Leysteinerz (40), Schrotflinte des Teufelsgebrabbels , Scharfschützenzielfernrohr" }
entries[137706] = { ["name"] = "Bauplan: Schwarzpulverladung", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schwarzpulverladung herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Schwarzpulverladung.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nSchwarzpulverladung\nBenutzen: Fügt einem Gegner innerhalb von bis zu 40 Metern ( 810 + 485 ) Feuerschaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Leysteinerz , Übergroße Sprengkapsel (30)" }
entries[137707] = { ["name"] = "Bauplan: Repetierbandagenflinte", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Repetierbandagenflinte herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Repetierbandagenflinte.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nRepetierbandagenflinte\nBenutzen: Heilt einen Verbündeten innerhalb von bis zu 40 Metern um ( 300 + 300 * 3) Gesundheit. (1 Min Abklingzeit)\n20 Aufladungen\nVerkaufspreis:\nBenötigt Leysteinerz (40), Schrotflinte des Teufelsgebrabbels , Echteisengewehrlauf" }
entries[137708] = { ["name"] = "Bauplan: Waffenpaket", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Waffenpaket herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Waffenpakets.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nWaffenpaket\nBenutzen: Schnallt Euch einige geladene Schusswaffen auf den Rücken. (15 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Leysteinerz (8), Schrotflinte des Teufelsgebrabbels (3), Anti-Höllenbestien-Raketenwerfer" }
entries[137709] = { ["name"] = "Bauplan: Automatikhammer", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Automatikhammer herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Automatikhammers.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nAutomatikhammer\nBenutzen: Stellt einen automatisierten Hammer auf, den alle nutzen können, um ihre Ausrüstung zu reparieren.\nVerkaufspreis:\nBenötigt Leysteinerz (18), Übergroße Sprengkapsel (10), Lockerer Abzug" }
entries[137710] = { ["name"] = "Bauplan: Fehlschlagdetektorpylon", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Fehlschlagdetektorpylon herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Fehlschlagdetektorpylonen.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nFehlschlagdetektorpylon\nBenutzen: Platziert einen elektrischen Pylonen auf dem Boden, der alle Gruppen- oder Schlachtzugsmitglieder innerhalb von 5 Metern nach dem Ende des Kampfes wiederbelebt.\n\nFunktioniert nicht bei Spielercharakteren ab Stufe 0 oder bei jenen, deren Geist freigelassen wurde. (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelsschiefer (4), Chaosblaster (2)" }
