entries[137719] = { ["name"] = "Bauplan: Stationärer Kugelspender", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen stationären Kugelspender herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines stationären Kugelspenders.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nStationärer Kugelspender\nBenutzen: Stellt einen Geschützturm auf, der Euch im Kampf unterstützt. (2 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBenötigt Leysteinerz (30), Schrotflinte des Teufelsgebrabbels , Scharfschützenzielfernrohr" }
entries[137720] = { ["name"] = "Bauplan: Schwarzpulverladung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schwarzpulverladung herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Schwarzpulverladung.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nSchwarzpulverladung\nBenutzen: Fügt einem Gegner innerhalb von bis zu 40 Metern ( 810 + 485 ) Feuerschaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Leysteinerz , Übergroße Sprengkapsel (20)" }
